    $scope.OnIntraOpChecklistSelect = function (obj, parentobj, mitem) {
        angular.forEach(parentobj.OrganizationCheckListDetails, function (item) {
            item.IsChecked = false;
        })
        obj.IsChecked = true;
        if (obj.Value == "Yes" || obj.Value == "Reviewed" || obj.Value == "Done") {
            mitem.IntraProcedurePhaseCheckList = mitem.IntraProcedurePhaseCheckList == 1 ? mitem.IntraProcedurePhaseCheckList : '';
            $scope.IntraOpObj.IsAllNurseCheckListChecked = $scope.IntraOpObj.IsAllNurseCheckListChecked == 1 ? $scope.IntraOpObj.IsAllNurseCheckListChecked : '';
        }
        if (obj.Value == "No" || obj.Value == "Not") {
            mitem.IntraProcedurePhaseCheckList = mitem.IntraProcedurePhaseCheckList == 2 ? mitem.IntraProcedurePhaseCheckList : '';
            $scope.IntraOpObj.IsAllNurseCheckListChecked = $scope.IntraOpObj.IsAllNurseCheckListChecked == 2 ? $scope.IntraOpObj.IsAllNurseCheckListChecked : '';
        }
        if (obj.Value == "N/A") {
            mitem.IntraProcedurePhaseCheckList = mitem.IntraProcedurePhaseCheckList == 3 ? mitem.IntraProcedurePhaseCheckList : '';
            $scope.IntraOpObj.IsAllNurseCheckListChecked = $scope.IntraOpObj.IsAllNurseCheckListChecked == 3 ? $scope.IntraOpObj.IsAllNurseCheckListChecked : '';
        }
    };

