    $scope.OnIntraOpAnesthChecklistSelect = function (obj, parentobj) {
        angular.forEach(parentobj.OrganizationCheckListDetails, function (item) {
            item.IsChecked = false;
        })
        obj.IsChecked = true;

        if (parentobj.CheckListCategoryId === 2) {
            if (obj.Value == "Yes" || obj.Value == "Done" || obj.Value == "Reviewed") {
                angular.forEach($scope.AscAnesthesistCheckList, function (item) {
                    if (parentobj.CheckListSubTypeId === item.CheckListSubTypeId) {
                        item.AllPreAnesthesiaCheckList = item.AllPreAnesthesiaCheckList == 1 ? item.AllPreAnesthesiaCheckList : '';
                        $scope.IntraOpObj.IsPreAnesthesiaCheckListChecked = $scope.IntraOpObj.IsPreAnesthesiaCheckListChecked == 1 ? $scope.IntraOpObj.IsPreAnesthesiaCheckListChecked : '';
                    }
                });
            }
            if (obj.Value == "No" || obj.Value == "Not") {
                angular.forEach($scope.AscAnesthesistCheckList, function (item) {

                    if (parentobj.CheckListSubTypeId === item.CheckListSubTypeId) {
                        item.AllPreAnesthesiaCheckList = item.AllPreAnesthesiaCheckList == 2 ? item.AllPreAnesthesiaCheckList : '';
                        $scope.IntraOpObj.IsPreAnesthesiaCheckListChecked = $scope.IntraOpObj.IsPreAnesthesiaCheckListChecked == 2 ? $scope.IntraOpObj.IsPreAnesthesiaCheckListChecked : '';
                    }
                });
            }
            if (obj.Value == "N/A") {
                angular.forEach($scope.AscAnesthesistCheckList, function (item) {

                    if (parentobj.CheckListSubTypeId === item.CheckListSubTypeId) {
                        item.AllPreAnesthesiaCheckList = item.AllPreAnesthesiaCheckList == 3 ? item.AllPreAnesthesiaCheckList : '';
                        $scope.IntraOpObj.IsPreAnesthesiaCheckListChecked = $scope.IntraOpObj.IsPreAnesthesiaCheckListChecked == 3 ? $scope.IntraOpObj.IsPreAnesthesiaCheckListChecked : '';
                    }
                });
            }


        }

    };
