    $scope.GenerateSasURL = function (data) {
        return new Promise(function (resolve, reject) {
            if (data && data.rows && data.rows.length > 0) {
                let s3UrlList = [];

                // Collect S3 URLs
                let mainRow = data.rows[0];

                if (mainRow.S3URL) {
                    s3UrlList.push({
                        "DocumentId": mainRow.PatientID || 0,
                        "OriginalS3URL": mainRow.S3URL || ""
                    });
                }

                if (mainRow.DocumentDetails && mainRow.DocumentDetails.length > 0) {
                    angular.forEach(mainRow.DocumentDetails, function (nitem) {
                        s3UrlList.push({
                            "DocumentId": nitem.DocumentId || 0,
                            "OriginalS3URL": nitem.S3URL || ""
                        });
                    });
                }


                $scope.getsasurl(s3UrlList)
                    .then(function (sasUrlListresp) {
                        sasUrlListresp.forEach(function (sasItem) {
                            if (mainRow.PatientID === sasItem.DocumentId) {
                                mainRow.S3URL = sasItem.SasUrl;
                            }

                            angular.forEach(mainRow.DocumentDetails, function (doc) {
                                if (doc.DocumentId === sasItem.DocumentId) {
                                    doc.S3URL = sasItem.SasUrl;
                                }
                            });
                        });

                        resolve(data);
                    })
                    .catch(function (error) {
                        reject(error);
                    });
            } else {
                reject("Failed to retrieve SAS token: Invalid patient data");
            }
        });
    }

    $scope.getsasurl = function (s3UrlList) {
        return new Promise(function (resolve, reject) {
            if (!s3UrlList || s3UrlList.length === 0) {
                reject("Invalid S3 URL List");
                return;
            }
            $http.post(url + "/Patient/GetSasUrl", s3UrlList, header)
                .then(function (response) {
                    if (response.data && Array.isArray(response.data)) {
                        resolve(response.data);
                    } else {
                        reject("SAS URL response is invalid");
                    }
                })
                .catch(function () {
                    reject("Failed to get SAS URL");
                });
        });
    }
