    $scope.newclicktime = function (item, type) {
        $scope.currentTime = $filter("date")(new Date(), "h:mm a");
        if (type == 'Crop') {
            item.CropHour = $scope.currentTime;
        }
        else if (type == 'PatientReceived') {
            item.PatientReceivedTime = $scope.currentTime;
        }
        else if (type == 'HandOffTime') {
            item.HandOffTime = $scope.currentTime;
            //  /*  $scope.IntraOpObj.NurseActionobj.SurgeryEndTime = angular.copy(item.HandOffTime);// for Hand-Off Notes*/
        }
        else if (type == 'HallStart') {
            item.HallEntranceStartTime = $scope.currentTime;
        }
        else if (type == 'HallEnd') {
            item.HallEntranceEndTime = $scope.currentTime;
        }
        else if (type == 'SurgeryStart') {
            item.SurgeryStartTime = $scope.currentTime;
        }
        else if (type == 'SurgeryEnd') {
            item.SurgeryEndTime = $scope.currentTime;
            /*$scope.IntraOpObj.HandOffTime = angular.copy(item.SurgeryEndTime);// for Hand-Off Notes	*/
        }
        else if (type == 'AnesthesiaStart') {
            item.AnesthesiaStartTime = $scope.currentTime;
        }
        else if (type == 'AnesthesiaEnd') {
            item.AnesthesiaEndTime = $scope.currentTime;
        }
        else if (type == 'FirstTime') {
            item.SurgicalFirstTime = $scope.currentTime;
        }
        else if (type == 'SecondTime') {
            item.SurgicalSecondTime = $scope.currentTime;
        }
        else if (type == 'FinalTime') {
            item.SurgicalFinalTime = $scope.currentTime;
        }
        else if (type == 'BeforeAnesthesia') {
            item.BeforeAnesthesiaTime = $scope.currentTime;
        }
    }
