    $scope.ChangesForNurseTemp = function (item) {
        console.log(item);
        if (item.PatientAscMedications.length > 0) {

            //$scope.IntraOpObj.Ordersobj.PatientAscMedications = item.PatientAscMedications || [];

            item = item || '';
            if (item.PatientAscMedications.length > 0) {
                angular.forEach(item.PatientAscMedications, function (Citem) {
                    Citem.SigfieldsShows = true;
                });
            }
            $scope.SelectedAscMedications = [];
            if (item != '') {
                $scope.SelectedAscMedications = angular.copy(item.PatientAscMedications) || [];
            }

            if ($scope.IntraOpObj.Ordersobj.PatientAscMedications.length == 0) {
                $scope.IntraOpObj.Ordersobj.PatientAscMedications = $scope.SelectedAscMedications || [];
            } else {
                if ($scope.SelectedAscMedications.length !== 0) {
                    angular.forEach($scope.SelectedAscMedications, function (Citem) {
                        var List = $filter("filter")($scope.IntraOpObj.Ordersobj.PatientAscMedications, function (Aitem, index) { return Aitem.MedicationName == Citem.MedicationName },);
                        if (List.length == 0) {
                            $scope.IntraOpObj.Ordersobj.PatientAscMedications.push(Citem);
                        }
                    });

                }
            }


        }
        if (item.PatientAscEyeDrops.length > 0) {
            $scope.IntraOpObj.Ordersobj.PatientAscEyeDrops = item.PatientAscEyeDrops || [];
        }
        if (item.PatientAscInjections.length > 0) {
            $scope.IntraOpObj.Ordersobj.PatientAscInjections = item.PatientAscInjections || [];
        }
        if (item.PatientAscInvestigations.length > 0) {
            $scope.IntraOpObj.Ordersobj.PatientAscInvestigations = item.PatientAscInvestigations || [];
        }
    }

