    $scope.init();
    $scope.SaveNurseTemplates = function () {

        if ($scope.IntraOpObj.Ordersobj.TemplateName === "") {
            alertify.error("Please Enter Template Name");
            return false;
        }
        var MedicationArray = $filter("filter")($scope.IntraOpObj.Ordersobj.PatientAscMedications, { "DeleteInd": "N" }, true);
        var EyeDropsArray = $filter("filter")($scope.IntraOpObj.Ordersobj.PatientAscEyeDrops, { "DeleteInd": "N" }, true);
        var InjectionsArray = $filter("filter")($scope.IntraOpObj.Ordersobj.PatientAscInjections, { "DeleteInd": "N" }, true);
        var InvestigationArray = $filter("filter")($scope.IntraOpObj.Ordersobj.PatientAscInvestigations, { "DeleteInd": "N" }, true);

        if (MedicationArray.length == 0 && EyeDropsArray.length == 0 && InjectionsArray.length == 0 && InvestigationArray.length == 0) {
            alertify.error("Please Select Medications or Investigation");
            return false;
        }
        var obj = {
            "UserId": $scope.UserId,
            "HospitalId": $scope.HospitalId,
            "AscOrderTemplateId": 0,
            "CategoryId": 1,
            "TemplateName": $scope.IntraOpObj.Ordersobj.TemplateName || "",
            "DeleteInd": "N",
            "PatientAscInvestigations": InvestigationArray || [],
            "PatientAscMedications": MedicationArray || [],
            "PatientAscEyeDrops": EyeDropsArray || [],
            "PatientAscInjections": InjectionsArray || [],
        }
        // return false;
        eHnotePatientDataService.AddUpdateUserAscOrderTemplates(obj).then(function (resp) {
            if (resp.data.status == "Success") {
                $scope.Nurseobj.EnterTemplateName = "";
                $scope.GetUserAscOrderTemplates();
                alertify.success("Template Created Successfully");
                $scope.IntraOpObj.Ordersobj.TemplateName = "";
            }

        }, function (err) {

        });
    }

