    $scope.DelectMedicationitem = function (item) {
        if (item.MedicationTypeId == 2) {
            var index = $scope.IntraOpObj.Ordersobj.PatientAscEyeDrops.indexOf(item);
            if (item.PatientAscMedicationId === 0) {
                if (index > -1) {
                    $scope.IntraOpObj.Ordersobj.PatientAscEyeDrops.splice(index, 1);
                }
            } else {
                $scope.IntraOpObj.Ordersobj.PatientAscEyeDrops[index].DeleteInd = 'Y';
            }

        }
        if (item.MedicationTypeId == 3) {
            var index = $scope.IntraOpObj.Ordersobj.PatientAscInjections.indexOf(item);
            if (item.PatientAscMedicationId === 0) {
                if (index > -1) {
                    $scope.IntraOpObj.Ordersobj.PatientAscInjections.splice(index, 1);
                }
            } else {
                $scope.IntraOpObj.Ordersobj.PatientAscInjections[index].DeleteInd = 'Y';
            }

        }

    };



