    $scope.isDisabled = false;
    $scope.CreateSlots = function () {

        $scope.GetAnesthesiaObj.StartTime = $scope.GetAnesthesiaObj.StartTime || '';
        if ($scope.GetAnesthesiaObj.StartTime == '') {
            alertify.error('Please select Start Time');
            return false;
        }
        $scope.GetAnesthesiaObj.EndTime = $scope.GetAnesthesiaObj.EndTime || '';
        if ($scope.GetAnesthesiaObj.EndTime == '') {
            alertify.error('Please select End Time');
            return false;
        }
        $scope.GetAnesthesiaObj.Duration = $scope.GetAnesthesiaObj.Duration || '';
        if ($scope.GetAnesthesiaObj.Duration == '') {
            alertify.error('Please select duration!');
            return false;
        }
        var count = 0;
        if ($scope.AnesthetistVitals.length > 0) {
            angular.forEach($scope.AnesthetistVitals, function (aitem) {
                if (aitem.VitalReadingList.length > 0) {
                    angular.forEach(aitem.VitalReadingList, function (nitem) {
                        if (nitem.Value != '') {
                            count = count + 1;
                        }
                    });
                }
            });
        }
        if (count > 0) {
            var r = alertify.confirm(
                "<b class='txt-centre'>Confirm!</b><h4 class='txt-body-centre pl-20 pr-20'>Are you sure you want to clear slot data? </h4>",
                function () {
                    $scope.IsActionsView = true;
                    var consultationTime = $scope.GetAnesthesiaObj.Duration;
                    if (consultationTime != undefined) {
                        var CurrentDate = $filter('date')(new Date(), 'MM-dd-yyyy');
                        $scope.timeslots = [];
                        var arr = $scope.GetAnesthesiaObj.StartTime.split(':');
                        var shour = $.trim(arr[0]);
                        var smin = $.trim(arr[1]);
                        var arr2 = $scope.GetAnesthesiaObj.EndTime.split(':')
                        var ehour = $.trim(arr2[0]);
                        var emin = $.trim(arr2[1]);
                        var startingTime = moment().hours(shour).minutes(smin);
                        var endingTime = moment().hours(ehour).minutes(emin);
                        var currentStartTime = angular.copy(startingTime);
                        var token = 1;
                        while (currentStartTime <= endingTime) {
                            var slotObj = {
                                "StartTime": currentStartTime.format("HH:mm"),
                                "EndTime": currentStartTime.add(consultationTime, "minute").format("HH:mm"),
                                "TokenNumber": token,
                                "Available": "Y"
                            }
                            token++;
                            var datetime = CurrentDate + "T" + slotObj.StartTime;
                            slotObj.NewStartTime = "";
                            slotObj.NewStartTime = $filter('date')(datetime, "hh:mm a");
                            $scope.timeslots.push(slotObj);
                        }
                    }
                    if ($scope.timeslots.length >= 13) {
                        $scope.timeslots = [];
                        $scope.AnesthesiaMedicines = [];
                        alertify.error('Please select the Time In Between 12 Slots');
                        return false;
                    }

                    if ($scope.timeslots.length > 0) {

                        $scope.justlist = [];
                        $scope.IntraOpAnesthetistVitals = [];
                        if ($scope.AnesthetistVitals.length > 0) {
                            $scope.AnesthetistVitals = angular.copy($scope.GetAnesthetistVitals());
                            angular.forEach($scope.AnesthetistVitals, function (item) {
                                // item.VitalReadingList = $scope.TempArray || [];
                                for (var k = 0; k < $scope.timeslots.length; k++) {
                                    var obj = {
                                        "VitalName": item.VitalName,
                                        "MainId": item.Id,
                                        "Value": '',
                                        "VitalSlotTime": $scope.timeslots[k].StartTime,
                                    }
                                    item.VitalReadingList.push(obj);
                                    $scope.IntraOpAnesthetistVitals.push(obj);
                                }
                            });
                        }
                    }
                }, function () {
                    return false;
                });
        } else {
            $scope.IsActionsView = true;
            var consultationTime = $scope.GetAnesthesiaObj.Duration;
            if (consultationTime != undefined) {

                var CurrentDate = $filter('date')(new Date(), 'MM-dd-yyyy');
                $scope.timeslots = [];

                var arr = $scope.GetAnesthesiaObj.StartTime.split(':');
                var shour = $.trim(arr[0]);
                var smin = $.trim(arr[1]);
                var arr2 = $scope.GetAnesthesiaObj.EndTime.split(':')
                var ehour = $.trim(arr2[0]);
                var emin = $.trim(arr2[1]);
                var startingTime = moment().hours(shour).minutes(smin);
                var endingTime = moment().hours(ehour).minutes(emin);



                var currentStartTime = angular.copy(startingTime);
                var token = 1;
                while (currentStartTime <= endingTime) {

                    var slotObj = {
                        "StartTime": currentStartTime.format("HH:mm"),
                        "EndTime": currentStartTime.add(consultationTime, "minute").format("HH:mm"),
                        "TokenNumber": token,
                        "Available": "Y"
                    }
                    token++;
                    var datetime = CurrentDate + "T" + slotObj.StartTime;
                    slotObj.NewStartTime = "";
                    slotObj.NewStartTime = $filter('date')(datetime, "hh:mm a");

                    $scope.timeslots.push(slotObj);

                }


            }
            if ($scope.timeslots.length >= 13) {
                $scope.timeslots = [];
                $scope.AnesthesiaMedicines = [];
                alertify.error('Please select the Time In Between 12 Slots');
                return false;
            }

            if ($scope.timeslots.length > 0) {


                $scope.IntraOpAnesthetistVitals = [];
                if ($scope.AnesthetistVitals.length > 0) {
                    $scope.AnesthetistVitals = angular.copy($scope.GetAnesthetistVitals());
                    angular.forEach($scope.AnesthetistVitals, function (item) {
                        // item.VitalReadingList = $scope.TempArray || [];
                        for (var k = 0; k < $scope.timeslots.length; k++) {
                            var obj = {
                                "VitalName": item.VitalName,
                                "MainId": item.Id,
                                "Value": '',
                                "VitalSlotTime": $scope.timeslots[k].StartTime,
                            }
                            item.VitalReadingList.push(obj);
                            $scope.IntraOpAnesthetistVitals.push(obj);
                        }
                    });
                }
            }
        }

        let len = $("canvas#myChart").length;
        if (len > 0) {
            $("canvas#myChart").remove();
        }

        $scope.isDisabled = true;

    };

