    $scope.SaveAnesthetistData = function (str) {
        if ($scope.AscCheckList.length > 0) {
            $scope.FinalAnesthesisChecklist = [];
            angular.forEach($scope.AscAnesthesistCheckList, function (item) {
                angular.forEach(item.CheckList, function (aitem) {
                    aitem.OrganizationCheckListDetails = aitem.OrganizationCheckListDetails || [];
                    var list1 = $filter("filter")(aitem.OrganizationCheckListDetails, { "IsChecked": true }, true);
                    let checkedvalue;
                    if (list1.length > 0) {
                        checkedvalue = list1[0];
                    }
                    if (checkedvalue !== undefined) {
                        if (checkedvalue.CheckListId === aitem.CheckListId) {
                            let obj = {
                                "PatientAscCheckListDetailId": aitem.PatientAscCheckListDetailId || 0,
                                "CheckListId": aitem.CheckListId,
                                "CheckListName": aitem.CheckListName,
                                "CheckListModuleId": aitem.CheckListModuleId,
                                "CheckListCategoryId": aitem.CheckListCategoryId,
                                "CheckListSubTypeId": aitem.CheckListSubTypeId,
                                "ParentOrganizationId": aitem.ParentOrganizationId,
                                "OrganizationPreOpCheckListId": checkedvalue.OrganizationPreOpCheckListId,
                                "DeleteInd": "N",
                                "OrganizationPreOpCheckListValueId": (checkedvalue != undefined) ? checkedvalue.OrganizationPreOpCheckListValueId : null,
                                "Value": (checkedvalue != undefined) ? checkedvalue.Value : ""
                            };
                            $scope.FinalAnesthesisChecklist.push(obj);
                        }
                    }
                })
            });
        }

        let tempAnesthetistVitals = [];
        if ($scope.AnesthetistVitals.length > 0) {
            angular.forEach($scope.AnesthetistVitals, function (kitem) {
                angular.forEach(kitem.VitalReadingList, function (jitem) {
                    let obj = {
                        "IntraOPAnesthesiaVitalsId": jitem.IntraOPAnesthesiaVitalsId || null,
                        "VitalName": jitem.VitalName,
                        "VitalId": jitem.MainId,
                        "Value": jitem.Value,
                        "VitalSlotTime": jitem.VitalSlotTime
                    };
                    tempAnesthetistVitals.push(obj);
                });
            });
        }

        let AnesthesiaStartTime = $scope.GetAnesthesiaObj.StartTime + ":" + "00";
        let AnesthesiaEndTime = $scope.GetAnesthesiaObj.EndTime + ":" + "00";
        let IntakeValue = $scope.IntraOpObj.IntakeValue || "";
        let OutputValue = $scope.IntraOpObj.OutputValue || "";
        let EBLValue = $scope.IntraOpObj.EBLValue || "";
        let ActionsObj;
        if (tempAnesthetistVitals.length > 0) {
            ActionsObj = {
                "IntraOPAnesthesiaActionId": $scope.IntraOpObj.Anesthetistobj.IntraOPAnesthesiaActionId || 0,
                "AppointmentId": $scope.cacheStorageItem.AppointmentId || null,
                "AnesthesiaTypeId": $scope.GetAnesthesiaObj.AnesthesiaTypeId,
                "AnesthesiaSlotStartTime": AnesthesiaStartTime,
                "AnesthesiaSlotEndTime": AnesthesiaEndTime,
                "Duration": parseInt($scope.GetAnesthesiaObj.Duration),
                "AnesthesiaVitalsArray": tempAnesthetistVitals || [],
                "AnesthesiaMedicines": $scope.AnesthesiaMedicines,
                "IntakeValue": IntakeValue || "",
                "OutputValue": OutputValue || "",
                "EBLValue": EBLValue || "",
                "DeleteInd": "N",
            };
        } else {
            ActionsObj = {};
        }

        if ($scope.IntraOpObj.AnesthesiaTypelist.length > 0) {
            angular.forEach($scope.IntraOpObj.AnesthesiaTypelist, function (kitem) {
                kitem.PatientSurgeryId = $scope.SurgeryDiagnosisObj.SelectedSurgery.PatientSurgeryId;
            });
        }


        var param = {
            "PatientASCIntraOPId": $scope.IntraOpObj.PatientASCIntraOPId || null,
            "UserId": $scope.UserId || null,
            "HospitalId": $scope.HospitalId || null,
            "PatientId": $scope.cacheStorageItem.PatientID || null,
            "AppointmentId": $scope.cacheStorageItem.AppointmentId || null,
            "PatientSurgeryId": $scope.SurgeryDiagnosisObj.SelectedSurgery.PatientSurgeryId,
            "Vitals": $scope.IntraOpObj.Vitals || [],
            "AllergyItems": $scope.IntraOpObj.AllergyItems || [],
            "SystemicHistory": $scope.IntraOpObj.SystemicHistory || [],
            "SurgicalHistory": $scope.IntraOpObj.SurgicalHistory || [],
            "PatientAscChecklist": $scope.FinalAnesthesisChecklist || [],
            //"PatientAscInvestigations": $scope.IntraOpObj.Anesthetistobj.PatientAscInvestigations || [],
            //"PatientAscEyeDrops": $scope.IntraOpObj.Anesthetistobj.PatientAscEyeDrops || [],
            //"PatientAscInjections": $scope.IntraOpObj.Anesthetistobj.PatientAscInjections || [],
            //"PatientAscMedications": $scope.IntraOpObj.Anesthetistobj.PatientAscMedications || [],
            "Actions": ActionsObj,
            "AnesthesiaReviewedBy": $scope.IntraOpObj.Anesthetistobj.AnesthesisId,
            "IntraOpChartStatus": (str === 'SignOff') ? "E" : "D",
            "StatusFlag": $scope.IntraOpObj.StatusFlag,
            "TempDocumentDetails": [],
            "DocumentDetails": [],
            "SignDate": $filter('date')($scope.currentDate, "yyyy-MM-dd"),
            "graphImg": $scope.IntraOpObj.graphImg,
            "PatientName": $scope.MainObj.PatientDetails.FullName,
            "AnesthetistNotes": $scope.IntraOpObj.AnesthetistNotes,
            "AnesthesiaTypelist": $scope.IntraOpObj.AnesthesiaTypelist,
            "S3URL": $scope.IntraOpObj.Anesthetistobj.S3URL,
            "ROSOverAllRemarks": $scope.IntraOpObj.ROSOverAllRemarks

        }

        $scope.AnesthetistFilesObj.TempImagesArray = $scope.AnesthetistFilesObj.TempImagesArray || [];
        if ($scope.AnesthetistFilesObj.TempImagesArray.length > 0) {
            angular.forEach($scope.AnesthetistFilesObj.TempImagesArray, function (item) {
                item.DocumentID = item.DocumentID || 0;
                var object = {
                    "file": item.file,
                    "S3URL": item.S3URL || '',
                    "DeleteInd": item.DeleteInd,
                    "DocumentID": item.DocumentID,
                    "FileName": item.FileName,
                    "FileExt": item.FileExt,
                    "FileTypeId": item.FileTypeId,
                    "DisplayName": item.DisplayName,
                };
                if (item.DocumentID === 0) {
                    param.TempDocumentDetails.push(object);
                    param.DocumentDetails.push(object);
                }
                else {
                    param.DocumentDetails.push(object);
                }
            });
        }

        //console.log(JSON.stringify(param));
        //return;

        eHnoteSurgeryService.AddupdateIntraOpAnesthesiaDetails(param, callbackSuccess, callbackError);
        function callbackSuccess(resp) {
            if (resp.Status === "Success") {
                alertify.success("Intra-op data successfully submitted!");
                $scope.IntraOpObj.IsEdit = false;
                $scope.IntraOpObj.IsShow = false;
                $scope.init();
                $scope.IntraOpObj.IsPreAnesthesiaCheckListChecked = '';
            } else {
                alertify.error("Some Error Occured");
            }
        };
        function callbackError(err) {
        }


    };




    $scope.ClearSlots = function (item) {
        var r = alertify.confirm("<b class='txt-centre'>Confirm !</b><h4 class='txt-body-centre'>Are you sure you want to Clear  ?", function () {
            item.AnesthesiaTypeId = '';
            item.AnesthesiaType = '';
            item.StartTime = '';
            item.EndTime = '';
            item.Duration = '';
            item.EndTimeType = 'AM';
            item.StartTimeType = 'AM';
            $scope.IsActionsView = false;
            $scope.IntraOpObj.ShowGraph = false;
            if ($scope.IntraOpAnesthetistVitals.length > 0) {
                angular.forEach($scope.IntraOpAnesthetistVitals, function (item) {
                    item.Value = '';
                })
            }
            if ($scope.AnesthesiaMedicines.length > 0) {
                angular.forEach($scope.AnesthesiaMedicines, function (item) {
                    if (item.IntraOPAnesthesiaMedicineId != 0) {
                        item.DeleteInd = "Y";
                    }
                })
            }

            let len = $("canvas#myChart").length;
            if (len > 0) {
                $("canvas#myChart").remove();
            }
            if (item.AnesthesiaTypeId == '' && item.AnesthesiaType == '' && item.StartTime == '' && item.EndTime == '') {
                alertify.error('All your data will be cleared')
            }

            $scope.isDisabled = false;
            $scope.$digest();
        }, function () {
            r = "You pressed Cancel!";
        });
    };

    $scope.getSlotEndTimesList = function (val) {
        var val = parseInt(val);
        val = val + 1;
        $scope.SlotEndValues = [];
        for (var i = val; i < 24; i++) {
            if (i > 9) {
                $scope.SlotEndValues.push({ 'time': i });
            } else {
                $scope.SlotEndValues.push({ 'time': '0' + i });
            }
        }
    };

