    $scope.AnesthesiaMedicalItems = function (item) {

        var obj = {
            "PatientAscMedicationId": 0,
            "MedicineId": item.MedicineId,
            "MedicationName": item.MedicineName,
            "PatientAscOrderId": 0,
            "OrganizationMedicationId": item.OrganizationPrescriptionId || 0,
            "Dosage": "",
            "Route": "",
            "MedicationTime": "",
            "Irrigation": "",
            "EquipmentId": "",
            "DeleteInd": "N",
            "Remarks": "",
            "MedicationTypeId": 1,
            "MedicationTimeList": [],
            "AnesthesiaMedicineValue": ""
        };

        var i = 0;
        if ($scope.AnesthesiaMedicines.length > 0) {
            angular.forEach($scope.AnesthesiaMedicines, function (Aitem) {
                if (Aitem.MedicineId === item.MedicineId && Aitem.DeleteInd == 'N') {
                    alertify.error('You have already entered this Medications');
                    i++;
                }
            });
        }

        if ($scope.NewTimeSlots.length > 0) {
            for (var j = 0; j < $scope.NewTimeSlots.length; j++) {
                var Sobj = {
                    "Value": '',
                    "SlotTime": $scope.NewTimeSlots[j].time
                }
                obj.MedicationTimeList.push(Sobj);
            }
        }

        let tempArray = $filter('filter')(obj.MedicationTimeList, { 'SlotTime': $scope.AnesthesiaGraphObj.SelectedTimeSlot }, true);
        if (tempArray.length == 0) {
            let tempObj = {
                "Value": '',
                "SlotTime": $scope.AnesthesiaGraphObj.SelectedTimeSlot
            }
            obj.MedicationTimeList.push(tempObj);
        }

        if (i === 0) {
            $scope.AnesthesiaMedicines.push(obj);
            $scope.AnesthesiaGraphObj.AnesthesiaMedicineObject = "";
            item = "";
        }
    };

