    $scope.selectIntraOpNurseImgs = function (files) {
        files = files || [];
        if (files.length > 0) {
            angular.forEach(files, function (item) {
                $scope.file = item;
                if ($scope.file != null) {

                    var pName = $scope.file.name, name = "";
                    var type = $scope.file.type.split("/")[1];
                    if (pName.length > 9) {
                        name = pName.substring(0, 9) + "..." + "." + type;
                    } else {
                        name = angular.copy(pName) + '.' + type;
                    }
                    var obj = {
                        "file": $scope.file,
                        "DocumentID": 0,
                        "DisplayName": $scope.file.name || "",
                        "FileName": $scope.file.name || "",
                        "FileExt": $scope.file.type,
                        "S3URL": "",
                        "DeleteInd": false,
                        "FileTypeId": 19,
                    };

                    $scope.NurseFilesObj.TempImagesArray.push(obj);

                    angular.element("input[type='file']").val(null);
                }
            });
        }
    };

