    $scope.IntraOpDynamicSummaryView = function (item) {
        let param = {
            "AppointmentId": $scope.cacheStorageItem.AppointmentId || null,
            "PatientSurgeryId": item.PatientSurgeryId || ""
        }

        console.log($scope.IntraOpSummaryObj)
        eHnoteSurgeryService.GetIntraOpDetails(param).then(function (resp) {
            // $scope.GenerateSasURL(resp.data);
            $scope.IntraOpObj.DocumentDetails = angular.copy(resp.data.rows[0].DocumentDetails);
            $scope.IntraOpObj.SurgicalHistory = angular.copy(resp.data.SurgicalHistory);
            $scope.IntraOpObj.SystemicHistory = angular.copy(resp.data.SystemicHistory);
            $scope.IntraOpObj.AllergyItems = angular.copy(resp.data.AllergyItems);

            if (resp.data.rows.length > 0) {

                $scope.IntraOpObj.PatientASCIntraOPId = resp.data.rows[0].PatientASCIntraOPId;
                $scope.IntraOpObj.IntraOpChartStatus = resp.data.rows[0].IntraOpChartStatus;
                $scope.IntraOpObj.IntraOpAnesthesiaChartStatus = resp.data.rows[0].IntraOpAnesthesiaChartStatus;
                $scope.IntraOpObj.IntraOpNurseChartStatus = resp.data.rows[0].IntraOpNurseChartStatus;
                $scope.IntraOpObj.StatusFlag = resp.data.rows[0].StatusFlag;
                $scope.IntraOpObj.NurseActionobj.NurseReviewedById = resp.data.rows[0].NurseReviewedById;
                /*$scope.IntraOpObj.Anesthetistobj.AnesthesisId = resp[4].data.rows[0].AnesthesistId;*/

                $scope.IntraOpObj.Vitals = angular.copy(resp.data.rows[0].Vitals);

                // ROS
                //$scope.IntraOpObj.SurgicalHistory = angular.copy(resp.data.rows[0].SurgicalHistory);
                //$scope.IntraOpObj.SystemicHistory = angular.copy(resp.data.rows[0].SystemicHistory);
                //SurgeryEndTime.IntraOpObj.AllergyItems = angular.copy(resp.data.rows[0].AllergyItems);

                // nurse checklist

                if (resp.data.rows[0].PatientAscChecklist.length > 0) {
                    angular.forEach(resp.data.rows[0].PatientAscChecklist, function (hitem) {
                        angular.forEach($scope.AscCheckList, function (kitem) {
                            if (hitem.CheckListCategoryId === kitem.CheckListCategoryId && hitem.CheckListSubTypeId === kitem.CheckListSubTypeId) {
                                angular.forEach(kitem.CheckList, function (jitem) {
                                    angular.forEach(jitem.OrganizationCheckListDetails, function (uitem) {
                                        if (hitem.CheckListId === jitem.CheckListId && uitem.Value === hitem.Value) {
                                            uitem.IsChecked = true;
                                            jitem.PatientAscCheckListDetailId = hitem.PatientAscCheckListDetailId || null;
                                        }
                                    });
                                });
                            }
                        });
                    });


                }

                // anesthesia checklist
                if (resp.data.rows[0].PatientAscChecklist.length > 0) {
                    angular.forEach(resp.data.rows[0].PatientAscChecklist, function (hitem) {
                        angular.forEach($scope.AscAnesthesistCheckList, function (kitem) {
                            if (hitem.CheckListCategoryId === kitem.CheckListCategoryId && hitem.CheckListSubTypeId === kitem.CheckListSubTypeId) {
                                angular.forEach(kitem.CheckList, function (jitem) {
                                    angular.forEach(jitem.OrganizationCheckListDetails, function (uitem) {
                                        if (hitem.CheckListId === jitem.CheckListId && uitem.Value === hitem.Value) {
                                            uitem.IsChecked = true;
                                            jitem.PatientAscCheckListDetailId = hitem.PatientAscCheckListDetailId || null;
                                        }
                                    });
                                });
                            }
                        });
                    });
                }
                $scope.IntraOpObj.PatientAscChecklist = resp.data.rows[0].PatientAscChecklist;
                // nurse actions
                $scope.IntraOpObj.NurseActionobj.Levelofconsciousness = resp.data.rows[0].Levelofconsciousness;
                $scope.IntraOpObj.NurseActionobj.LevelofconsciousnessNotes = resp.data.rows[0].LevelofconsciousnessNotes;
                $scope.IntraOpObj.NurseActionobj.PatientPosition = resp.data.rows[0].PatientPosition;
                $scope.IntraOpObj.NurseActionobj.PatientPositionNotes = resp.data.rows[0].PatientPositionNotes;
                $scope.IntraOpObj.NurseActionobj.SafetyDevicePosition = resp.data.rows[0].SafetyDevicePosition;
                $scope.IntraOpObj.NurseActionobj.SafetyDevicePositionNotes = resp.data.rows[0].SafetyDevicePositionNotes;
                $scope.IntraOpObj.NurseActionobj.SkinPreparation = resp.data.rows[0].SkinPreparation;
                $scope.IntraOpObj.NurseActionobj.SkinPreparationNotes = resp.data.rows[0].SkinPreparationNotes;
                $scope.IntraOpObj.NurseActionobj.AreaNotes = resp.data.rows[0].AreaNotes;
                $scope.IntraOpObj.EspecimenLab = resp.data.rows[0].EspecimenLab;
                $scope.IntraOpObj.Pathology = resp.data.rows[0].EspecimenLabNotes;
                if (resp[4].data.rows[0].CropHour != "00:00:00") {
                    $scope.IntraOpObj.NurseActionobj.CropHour = resp.data.rows[0].CropHour;
                } else {
                    $scope.IntraOpObj.NurseActionobj.CropHour = "";
                }

                // Patient Goals

                if (resp.data.rows[0].PatientAscPatientGoal.length > 0) {

                    $scope.IntraOpObj.NurseActionobj.PatientAscPatientGoal = resp.data.rows[0].PatientAscPatientGoal;
                    angular.forEach(resp.data.rows[0].PatientAscPatientGoal, function (jitem) {
                        angular.forEach($scope.MasterAscPatientGoal, function (hitem) {
                            if (hitem.MasterPatientGoalId === jitem.MasterPatientGoalId) {
                                hitem.Value = jitem.Value;
                                hitem.ASCIntraOPPatientGoalId = jitem.ASCIntraOPPatientGoalId;
                            }
                        });
                    });
                }

                // surgery staff
                $scope.IntraOpObj.NurseActionobj.SurgeonId = resp.data.rows[0].SurgeonId;
                $scope.IntraOpObj.NurseActionobj.TechnicianId = resp.data.rows[0].TechnicianId;
                $scope.IntraOpObj.NurseActionobj.AnesthesistId = resp.data.rows[0].AnesthesistId;
                $scope.IntraOpObj.NurseActionobj.NurseId = resp.data.rows[0].NurseId;
                $scope.IntraOpObj.NurseActionobj.ReliefId = resp.data.rows[0].ReliefId;
                $scope.IntraOpObj.NurseActionobj.SupportingStaffId = resp.data.rows[0].SupportingStaffId;
                $scope.IntraOpObj.NurseActionobj.AdditionalStaffId = resp.data.rows[0].AdditionalStaffId;
                console.log($scope.allUserList)

                angular.forEach($scope.allUserList, function (item) {

                    if ($scope.IntraOpObj.NurseActionobj.SurgeonId == item.DoctorID) {
                        $scope.IntraOpObj.NurseActionobj.SurgeonName = item.UserFullName;
                    }
                    if ($scope.IntraOpObj.NurseActionobj.TechnicianId == item.DoctorID) {
                        $scope.IntraOpObj.NurseActionobj.TechnicianName = item.UserFullName;
                    }
                    if ($scope.IntraOpObj.NurseActionobj.AnesthesistId == item.DoctorID) {
                        $scope.IntraOpObj.NurseActionobj.AnesthesistName = item.UserFullName;
                    }
                    if ($scope.IntraOpObj.NurseActionobj.NurseId == item.DoctorID) {
                        $scope.IntraOpObj.NurseActionobj.NurseName = item.UserFullName;
                    }
                    if ($scope.IntraOpObj.NurseActionobj.ReliefId == item.DoctorID) {
                        $scope.IntraOpObj.NurseActionobj.ReliefName = item.UserFullName;
                    }
                    if ($scope.IntraOpObj.NurseActionobj.SupportingStaffId == item.DoctorID) {
                        $scope.IntraOpObj.NurseActionobj.SupportingStaffName = item.UserFullName;
                    }
                    if ($scope.IntraOpObj.NurseActionobj.AdditionalStaffId == item.DoctorID) {
                        $scope.IntraOpObj.NurseActionobj.AdditionalStaffName = item.UserFullName;
                    }
                })

                //Surgical Count

                $scope.IntraOpObj.NurseActionobj.SurgicalFirstNeedles = resp.data.rows[0].SurgicalFirstNeedles;
                $scope.IntraOpObj.NurseActionobj.SurgicalFirstBlades = resp.data.rows[0].SurgicalFirstBlades;
                $scope.IntraOpObj.NurseActionobj.SurgicalFirstOthers = resp.data.rows[0].SurgicalFirstOthers;
                $scope.IntraOpObj.NurseActionobj.SurgicalFirstVerifiedBy = resp.data.rows[0].SurgicalFirstVerifiedBy;
                $scope.IntraOpObj.NurseActionobj.SurgicalFirstTime = resp.data.rows[0].SurgicalFirstTime;

                $scope.IntraOpObj.NurseActionobj.SurgicalSecondNeedles = resp.data.rows[0].SurgicalSecondNeedles;
                $scope.IntraOpObj.NurseActionobj.SurgicalSecondBlades = resp.data.rows[0].SurgicalSecondBlades;
                $scope.IntraOpObj.NurseActionobj.SurgicalSecondOthers = resp.data.rows[0].SurgicalSecondOthers;
                $scope.IntraOpObj.NurseActionobj.SurgicalSecondVerifiedBy = resp.data.rows[0].SurgicalSecondVerifiedBy;
                $scope.IntraOpObj.NurseActionobj.SurgicalSecondTime = resp.data.rows[0].SurgicalSecondTime;

                $scope.IntraOpObj.NurseActionobj.SurgicalFinalNeedles = resp.data.rows[0].SurgicalFinalNeedles;
                $scope.IntraOpObj.NurseActionobj.SurgicalFinalBlades = resp.data.rows[0].SurgicalFinalBlades;
                $scope.IntraOpObj.NurseActionobj.SurgicalFinalOthers = resp.data.rows[0].SurgicalFinalOthers;
                $scope.IntraOpObj.NurseActionobj.SurgicalFinalVerifiedBy = resp.data.rows[0].SurgicalFinalVerifiedBy;
                $scope.IntraOpObj.NurseActionobj.SurgicalFinalTime = resp.data.rows[0].SurgicalFinalTime;

                //Surgery Times
                $scope.IntraOpObj.NurseActionobj.SurgeryRoomNo = resp.data.rows[0].SurgeryRoomNo;
                $scope.IntraOpObj.NurseActionobj.HallEntranceStartTime = resp.data.rows[0].HallEntranceStartTime;
                $scope.IntraOpObj.NurseActionobj.HallEntranceEndTime = resp.data.rows[0].HallEntranceEndTime;
                $scope.IntraOpObj.NurseActionobj.SurgeryStartTime = resp.data.rows[0].SurgeryStartTime;
                $scope.IntraOpObj.NurseActionobj.SurgeryEndTime = resp.data.rows[0].SurgeryEndTime;
                $scope.IntraOpObj.NurseActionobj.AnesthesiaStartTime = resp.data.rows[0].AnesthesiaStartTime;
                $scope.IntraOpObj.NurseActionobj.AnesthesiaEndTime = resp.data.rows[0].AnesthesiaEndTime;


                // surgeon

                $scope.IntraOpObj.MedicationsList = angular.copy(resp.data.rows[0].SurgeonMedications);
                $scope.IntraOpObj.InvestigationsList = angular.copy(resp.data.rows[0].SurgeonInvestigations);
                $scope.IntraOpObj.SurgeonOperativeNotes = resp.data.rows[0].SurgeonOperativeNotes;
                //  $scope.IntraOpObj.SurgeonOperativeNotes = $scope.IntraOpObj.SurgeonOperativeNotes.replace(/\n/g, '<br>');
                $scope.IntraOpObj.Complications = resp.data.rows[0].SurgeonComplications;

                // orders
                $scope.IntraOpObj.Ordersobj.PatientAscMedications = angular.copy(resp.data.rows[0].PatientAscMedications) || [];
                $scope.IntraOpObj.Ordersobj.PatientAscInjections = angular.copy(resp.data.rows[0].PatientAscInjections) || [];
                $scope.IntraOpObj.Ordersobj.PatientAscEyeDrops = angular.copy(resp.data.rows[0].PatientAscEyeDrops) || [];
                $scope.IntraOpObj.Ordersobj.PatientAscInvestigations = angular.copy(resp.data.rows[0].PatientAscInvestigations) || [];

                //$scope.IntraOpObj.Anesthetistobj.PatientAscMedications = angular.copy(resp[4].data.rows[0].AnesthetistAscMedications);
                //$scope.IntraOpObj.Anesthetistobj.PatientAscEyeDrops = angular.copy(resp[4].data.rows[0].AnesthetistAscEyeDrops);
                //$scope.IntraOpObj.Anesthetistobj.PatientAscInjections = angular.copy(resp[4].data.rows[0].AnesthetistAscInjections);
                //$scope.IntraOpObj.Anesthetistobj.PatientAscInvestigations = angular.copy(resp[4].data.rows[0].AnesthetistInvestigations);
                $scope.NurseFilesObj.TempImagesArray = [];
                $scope.AnesthetistFilesObj.TempImagesArray = [];
                $scope.SurgeonFilesObj.TempImagesArray = [];

                $scope.IntraOpAnesthetistVitals = [];
                //Anesthesia
                if (resp.data.rows[0].Actions.length > 0) {
                    $scope.IntraOpObj.Anesthetistobj.IntraOPAnesthesiaActionId = resp.data.rows[0].Actions[0].IntraOPAnesthesiaActionId;
                    if (resp.data.rows[0].Actions[0].AnesthesiaTypeId != undefined) {
                        $scope.GetAnesthesiaObj.AnesthesiaTypeId = resp.data.rows[0].Actions[0].AnesthesiaTypeId;
                        let anesthesiaStart = resp.data.rows[0].Actions[0].AnesthesiaSlotStartTime;
                        let arr1 = anesthesiaStart.split(":");
                        let anesthesiaEnd = resp.data.rows[0].Actions[0].AnesthesiaSlotEndTime;
                        let arr2 = anesthesiaEnd.split(":");

                        $scope.GetAnesthesiaObj.StartTime = arr1[0];
                        $scope.getSlotEndTimesList(arr1[0]);
                        $scope.GetAnesthesiaObj.EndTime = arr2[0];
                        $scope.GetAnesthesiaObj.Duration = resp.data.rows[0].Actions[0].Duration;
                        $scope.GetAnesthesiaObj.Duration = $scope.GetAnesthesiaObj.Duration || 0;
                        if ($scope.GetAnesthesiaObj.Duration != 0) {
                            $scope.GetAnesthesiaObj.Duration = $scope.GetAnesthesiaObj.Duration.toString();
                        }

                        if (resp.data.rows[0].Actions[0].AnesthesiaVitalsArray.length > 0) {

                            let CurrentDate = $filter('date')(new Date(), 'MM-dd-yyyy');
                            $scope.timeslots = [];

                            let arr = $scope.GetAnesthesiaObj.StartTime.split(':');
                            let shour = $.trim(arr[0]);
                            let smin = $.trim(arr[1]);
                            let arr2 = $scope.GetAnesthesiaObj.EndTime.split(':')
                            let ehour = $.trim(arr2[0]);
                            let emin = $.trim(arr2[1]);
                            let startingTime = moment().hours(shour).minutes(smin);
                            let endingTime = moment().hours(ehour).minutes(emin);

                            let currentStartTime = angular.copy(startingTime);
                            let token = 1;
                            //let consultationTime = resp.data.rows[0].Actions[0].Duration;
                            let consultationTime = $scope.GetAnesthesiaObj.Duration;

                            while (currentStartTime <= endingTime) {

                                let slotObj = {
                                    "StartTime": currentStartTime.format("HH:mm"),
                                    "EndTime": currentStartTime.add(consultationTime, "minute").format("HH:mm"),
                                    "TokenNumber": token,
                                    "Available": "Y"
                                }
                                token++;
                                let datetime = CurrentDate + "T" + slotObj.StartTime;
                                slotObj.NewStartTime = "";
                                slotObj.NewStartTime = $filter('date')(datetime, "hh:mm a");

                                $scope.timeslots.push(slotObj);

                            }

                            $scope.IntraOpObj.ShowGraph = true;
                            $scope.IsActionsView = true;
                            $scope.IntraOpAnesthetistVitals = [];
                            if ($scope.AnesthetistVitals.length > 0) {
                                $scope.AnesthetistVitals = angular.copy($scope.GetAnesthetistVitals());
                                angular.forEach($scope.AnesthetistVitals, function (item) {
                                    for (var k = 0; k < $scope.timeslots.length; k++) {
                                        var obj = {
                                            "VitalName": item.VitalName,
                                            "MainId": item.Id,
                                            "Value": '',
                                            "VitalSlotTime": $scope.timeslots[k].StartTime,
                                        }
                                        item.VitalReadingList.push(obj);
                                        $scope.IntraOpAnesthetistVitals.push(obj);
                                    }
                                });
                            }
                            angular.forEach(resp.data.rows[0].Actions[0].AnesthesiaVitalsArray, function (jitem) {
                                angular.forEach($scope.AnesthetistVitals, function (kitem) {
                                    if (kitem.Id === jitem.VitalId) {
                                        angular.forEach(kitem.VitalReadingList, function (mitem) {
                                            if (jitem.VitalSlotTime === mitem.VitalSlotTime) {
                                                mitem.Value = jitem.Value;
                                                mitem.IntraOPAnesthesiaVitalsId = jitem.IntraOPAnesthesiaVitalsId;
                                            }
                                        });
                                    }

                                });
                            });
                        }

                        if (resp.data.rows[0].Actions[0].AnesthesiaMedicines.length > 0) {
                            $scope.AnesthesiaMedicines = angular.copy(resp.data.rows[0].Actions[0].AnesthesiaMedicines);
                        }
                    }
                }
            } else {
                $scope.IntraOpObj.PatientASCIntraOPId = 0;
                $scope.IntraOpObj.Vitals = [];

            }

        }, function (err) {
            alertify.error("Fetching Data failed!");
            console.log(err);
        });
    }

