    $scope.ConvertDate = function (Data) {
        if (Data.length > 0) {
            angular.forEach(Data, function (item) {
                item.Duration = item.Duration || null;
                if (item.Duration == null) {
                    item.DurationType = 'D';
                    var today = new Date();
                    var dd = today.getDate();
                    var mm = today.getMonth() + 1; //January is 0!
                    var yyyy = today.getFullYear();
                    if (dd < 10) {
                        dd = '0' + dd
                    }
                    if (mm < 10) {
                        mm = '0' + mm
                    }
                    today = yyyy + '/' + mm + '/' + dd;
                    var date2 = new Date(today);
                    var todate = $filter('date')(item.DurationDate, "yyyy/MM/dd");
                    var date1 = new Date(todate);
                    var timeDiff = Math.abs(date2.getTime() - date1.getTime());
                    $scope.dayDifference = Math.ceil(timeDiff / (1000 * 3600 * 24));
                    item.Duration = $scope.dayDifference;
                }
            });
        }
    }

    $scope.getOrganizationMedicationSigitems = function (text) {
        text = text || '';
        var params = {
            "OrganizationId": $scope.HospitalId,
            "SearchText": text || '',
            "IsFrequent": "Y",
            "PageSize": 10,
            "PageNumber": 1

        };
        if (text != "") {
            params.IsFrequent = "N";
        }
        return eHnotePatientDataService.GetOrganizationMedicationSigList(params).then(function (resp) {
            if (resp.data.rows.length !== 0) {
                if (resp.data.rows !== undefined) {
                    return resp.data.rows.map(function (item) {
                        return item;
                    });
                }
            }

        });

    };
