    $scope.GetAnesthesiaGraphObj = function () {
        return {
            "SelectedTimeSlot": "",
            "SystolicValue": "",
            "DiastolicValue": "",
            "PulseValue": "",
            "RespValue": "",
            "SpO2Value": "",
            "ETCO2Value": "",
            "ECGValue": "",
            "O2SatValue": "",
            "AnesthesiaMedicineObject": "",
            "ShowVitalParams": false,
        };
    };

    $scope.AnesthesiaGraphObj = angular.copy($scope.GetAnesthesiaGraphObj());

    $scope.AddAnesthesiaVitalParameters = function () {

        //if ($scope.AnesthesiaGraphObj.SystolicValue == "" && $scope.AnesthesiaGraphObj.DiastolicValue == "" && $scope.AnesthesiaGraphObj.PulseValue == "" &&
        //    $scope.AnesthesiaGraphObj.RespValue == "" && $scope.AnesthesiaGraphObj.SpO2Value == "" && $scope.AnesthesiaGraphObj.ETCO2Value == "" &&
        //    $scope.AnesthesiaGraphObj.ECGValue == "" && $scope.AnesthesiaGraphObj.O2SatValue == "") {
        //    alertify.error("Please enter value!");
        //    return;
        //}

        angular.forEach($scope.AnesthetistVitals, function (item) {

            angular.forEach(item.VitalReadingList, function (kitem) {
                let splitarray = kitem.VitalSlotTime.split(":");
                let stringCounter = splitarray.join("");
                let counter = parseInt(stringCounter);

                kitem.counter = counter;
            });

            let splitarray = $scope.AnesthesiaGraphObj.SelectedTimeSlot.split(":");
            let stringCounter = splitarray.join("");
            let counter = parseInt(stringCounter);

            if (item.Id == 1) {
                let obj = {
                    "VitalName": "Systolic Pressure",
                    "DeleteInd": 'N',
                    "MainId": 1,
                    "Value": $scope.AnesthesiaGraphObj.SystolicValue,
                    "VitalSlotTime": $scope.AnesthesiaGraphObj.SelectedTimeSlot,
                    "counter": counter
                };
                item.VitalReadingList.push(obj);
            }

            if (item.Id == 2) {
                let obj = {
                    "VitalName": "Diastolic Pressure",
                    "DeleteInd": 'N',
                    "MainId": 2,
                    "Value": $scope.AnesthesiaGraphObj.DiastolicValue,
                    "VitalSlotTime": $scope.AnesthesiaGraphObj.SelectedTimeSlot,
                    "counter": counter
                };
                item.VitalReadingList.push(obj);
            }

            if (item.Id == 3) {
                let obj = {
                    "VitalName": "Pulse",
                    "MainId": 3,
                    "DeleteInd": 'N',
                    "Value": $scope.AnesthesiaGraphObj.PulseValue,
                    "VitalSlotTime": $scope.AnesthesiaGraphObj.SelectedTimeSlot,
                    "counter": counter
                };
                item.VitalReadingList.push(obj);
            }

            if (item.Id == 4) {
                let obj = {
                    "VitalName": "Resp.Rate",
                    "MainId": 4,
                    "DeleteInd": 'N',
                    "Value": $scope.AnesthesiaGraphObj.RespValue,
                    "VitalSlotTime": $scope.AnesthesiaGraphObj.SelectedTimeSlot,
                    "counter": counter
                };
                item.VitalReadingList.push(obj);
            }

            //if (item.Id == 5) {
            //    let obj = {
            //        "VitalName": "Spo 2",
            //        "MainId": 5,
            //        "Value": $scope.AnesthesiaGraphObj.SpO2Value,
            //        "VitalSlotTime": $scope.AnesthesiaGraphObj.SelectedTimeSlot,
            //    };
            //    item.VitalReadingList.push(obj);
            //}

            if (item.Id == 6) {
                let obj = {
                    "VitalName": "O2 Saturation",
                    "MainId": 6,
                    "DeleteInd": 'N',
                    "Value": $scope.AnesthesiaGraphObj.O2SatValue,
                    "VitalSlotTime": $scope.AnesthesiaGraphObj.SelectedTimeSlot,
                    "counter": counter
                };
                item.VitalReadingList.push(obj);
            }

            if (item.Id == 7) {
                let obj = {
                    "VitalName": "EKG",
                    "MainId": 7,
                    "DeleteInd": 'N',
                    "Value": $scope.AnesthesiaGraphObj.ECGValue,
                    "VitalSlotTime": $scope.AnesthesiaGraphObj.SelectedTimeSlot,
                    "counter": counter
                };
                item.VitalReadingList.push(obj);
            }

            if (item.Id == 8) {
                let obj = {
                    "VitalName": "ETCO2",
                    "MainId": 8,
                    "DeleteInd": 'N',
                    "Value": $scope.AnesthesiaGraphObj.ETCO2Value,
                    "VitalSlotTime": $scope.AnesthesiaGraphObj.SelectedTimeSlot,
                    "counter": counter
                };
                item.VitalReadingList.push(obj);
            }


            if (item.Id == 9) {
                let obj = {
                    "VitalName": "Temparature",
                    "MainId": 9,
                    "DeleteInd": 'N',
                    "Value": "",
                    "VitalSlotTime": $scope.AnesthesiaGraphObj.SelectedTimeSlot,
                    "counter": counter
                };
                item.VitalReadingList.push(obj);
            }
            if (item.Id == 10) {
                let obj = {
                    "VitalName": "Note",
                    "MainId": 10,
                    "DeleteInd": 'N',
                    "Value": "",
                    "VitalSlotTime": $scope.AnesthesiaGraphObj.SelectedTimeSlot,
                    "counter": counter
                };
                item.VitalReadingList.push(obj);
            }

        });

        // arranging in ascending order of time
        angular.forEach($scope.AnesthetistVitals, function (item) {
            if (item.VitalReadingList.length > 0) {
                let filteredData = $filter('orderBy')(item.VitalReadingList, 'counter');
                item.VitalReadingList = angular.copy(filteredData);
            }
        });

        $scope.NewTimeSlots = [];

        let tempArray = $filter('filter')($scope.AnesthetistVitals, { 'VitalName': 'Systolic Pressure' }, true);
        if (tempArray.length > 0) {
            if (tempArray[0].VitalReadingList.length > 0) {
                angular.forEach(tempArray[0].VitalReadingList, function (kitem) {
                    kitem.DeleteInd = kitem.DeleteInd || 'N';
                    if (kitem.DeleteInd == 'N') {
                        let dummydate = "2024-01-01";
                        let dummydatetime = dummydate + " " + kitem.VitalSlotTime;
                        let newtime = moment(dummydatetime, "YYYY-MM-DD HH:mm").format("hh:mm A");
                        let tempArray = kitem.VitalSlotTime.split(":");
                        let stringCounter = tempArray.join("");
                        let counter = parseInt(stringCounter);
                        $scope.NewTimeSlots.push({ 'time': kitem.VitalSlotTime, 'NewTime': newtime, 'counter': counter, 'SlotNotes': '' });
                    }

                });
            }
        }

        let filteredData = $filter('orderBy')($scope.NewTimeSlots, 'counter');
        if (filteredData.length > 0) {
            $scope.IntraOpObj.InTime = filteredData[0].NewTime;
            $scope.IntraOpObj.OutTime = filteredData[filteredData.length - 1].NewTime;
            $scope.IntraOpObj.NurseActionobj.HandOffTime = filteredData[filteredData.length - 1].NewTime;

          
            if ($scope.ParentObj.IsIOJParentOrganization) {
                $scope.IntraOpObj.NurseActionobj.HallEntranceEndTime = filteredData[filteredData.length - 1].NewTime;
                $scope.IntraOpObj.NurseActionobj.SurgeryEndTime = filteredData[filteredData.length - 1].NewTime;
                $scope.IntraOpObj.NurseActionobj.AnesthesiaEndTime = filteredData[filteredData.length - 1].NewTime;
                if ($scope.IntraOpObj.HandOffReviewedBy != '' && $scope.IntraOpObj.HandOffReviewedBy != null) {
                    $scope.IntraOpObj.HandOffTime = filteredData[filteredData.length - 1].NewTime;
                }
            }

           

        }

        if ($scope.NewTimeSlots.length > 0) {
            angular.forEach($scope.NewTimeSlots, function (kitem) {
                kitem.lastbutoneIND = false;
            });
            if ($scope.NewTimeSlots.length == 2 || $scope.NewTimeSlots.length > 2) {
                $scope.NewTimeSlots[$scope.NewTimeSlots.length - 2].lastbutoneIND = true;
            }
        }

        angular.forEach($scope.AnesthesiaMedicines, function (item) {
            let tempArray = $filter('filter')(item.MedicationTimeList, { 'SlotTime': $scope.AnesthesiaGraphObj.SelectedTimeSlot }, true);
            if (tempArray.length == 0) {
                let tempObj = {
                    "Value": '',
                    "SlotTime": $scope.AnesthesiaGraphObj.SelectedTimeSlot
                }
                item.MedicationTimeList.push(tempObj);
            }
            angular.forEach(item.MedicationTimeList, function (hitem) {
                if (hitem.SlotTime == $scope.AnesthesiaGraphObj.SelectedTimeSlot) {
                    hitem.Value = item.AnesthesiaMedicineValue;
                }
            });
        });

        $scope.AnesthesiaGraphObj = angular.copy($scope.GetAnesthesiaGraphObj());
    };

    $scope.ChangeHandofftime = function () {
        /* $scope.IntraOpObj.HandOffTime = $scope.IntraOpObj.NurseActionobj.SurgeryEndTime;*/
        $scope.SetHandOffTimeByLatestSlot();
    }
    $scope.ChangeVitalsReadingValues = function () {
        if ($scope.AnesthetistVitals.length > 0) {
            angular.forEach($scope.AnesthetistVitals, function (aitem) {
                if (aitem.VitalReadingList.length > 0) {
                    angular.forEach(aitem.VitalReadingList, function (nitem) {
                        if (nitem.Value != '') {
                            $scope.IsActionsView = true;
                        }
                    });
                }

            });
        }
    }

    $scope.OnSelectTimeSlot = function (val) {
        $scope.AnesthetistVitals = $scope.AnesthetistVitals || [];
        let counter = 0;
        angular.forEach($scope.AnesthetistVitals, function (item) {
            let tempArray = $filter('filter')(item.VitalReadingList, { 'VitalSlotTime': val, "DeleteInd": 'N' }, true);
            if (tempArray.length > 0) {
                counter++;
            }
        });

        if (counter > 0) {
            alertify.error("Data already added!");
            return;
        }

        let Anestcounter1 = 0;
        angular.forEach($scope.AnesthetistVitals, function (item) {
            if (item.VitalReadingList.length > 0) {
                let lastObject = item.VitalReadingList[item.VitalReadingList.length - 1];
                lastObject.Value = lastObject.Value || '';
                if (lastObject.Value == '' && lastObject.DeleteInd == 'N') {
                    Anestcounter1++;
                }
            }
        });
        //if (Anestcounter1 == 7) {
        //    alertify.error("Please enter value.");
        //    return false;
        //}

        let Anestcounter2 = 0;
        angular.forEach($scope.AnesthetistVitals, function (item) {
            if (item.VitalReadingList.length > 0) {
                let firstObject = item.VitalReadingList[0];
                firstObject.Value = firstObject.Value || '';
                if (firstObject.Value == '' && firstObject.DeleteInd == 'N') {
                    Anestcounter2++;
                }
            }
        });
        //if (Anestcounter2 == 7) {
        //    alertify.error("Please enter value.");
        //    return false;
        //}

        $scope.AnesthesiaGraphObj = angular.copy($scope.GetAnesthesiaGraphObj());
        $scope.AnesthesiaGraphObj.SelectedTimeSlot = val;
        /*$scope.AnesthesiaGraphObj.ShowVitalParams = true;*/
        $scope.AddAnesthesiaVitalParameters();

        $scope.SetHandOffTimeByLatestSlot();
    };

    $scope.SetHandOffTimeByLatestSlot = function () {

        var matchedSlot = null;
        var reviewedBy = $scope.IntraOpObj.HandOffReviewedBy || null;
        if ($scope.NewTimeSlots && $scope.NewTimeSlots.length > 0) {        
            matchedSlot = $scope.NewTimeSlots[$scope.NewTimeSlots.length - 1];
        }
        if (matchedSlot && reviewedBy) {
            $scope.IntraOpObj.HandOffTime = matchedSlot.NewTime;
        } else {
            $scope.IntraOpObj.HandOffTime = null;
        }
    };


