    $scope.AddOthersImplant = function (item, type) {
        $scope.ImplantsObj.CategoryId = 10;
        if ($scope.ImplantsObj.SubCategoryId == null) {
            alertify.error("Please select the type!");
            return false;
        }
        if ($scope.ImplantsObj.ImplantName == '') {
            alertify.error("Please enter the name!");
            return false;
        }
        if ($scope.ImplantsObj.ManufacturerId == null) {
            alertify.error("Please select the manufacturer!");
            return false;
        }
        if ($scope.ImplantsObj.SerialNumber == '') {
            alertify.error("Please enter the serial number!");
            return false;
        }
        if ($scope.ImplantsObj.StatusId == null) {
            alertify.error("Please select the status!");
            return false;
        }
        if ($scope.ImplantsObj.OrganId == null) {
            alertify.error("Please select the organ!");
            return false;
        }
        let LensArray = $filter('filter')($scope.SubTypecategory, { 'SubCategoryId': $scope.ImplantsObj.SubCategoryId }, true);
        if (LensArray.length > 0) {
            $scope.ImplantsObj.SubCategoryName = LensArray[0].SubCategoryName;
        }


        let ManufacturerArray = $filter('filter')($scope.Manufacturers, { 'ManufacturerId': $scope.ImplantsObj.ManufacturerId }, true);
        if (ManufacturerArray.length > 0) {
            $scope.ImplantsObj.Manufacturer = ManufacturerArray[0].Manufacturer;
        }

        let OrganArray = $filter('filter')($scope.ImplantsObj.OrganArray, { 'OrganId': $scope.ImplantsObj.OrganId }, true);
        if (OrganArray.length > 0) {
            $scope.ImplantsObj.OrganName = OrganArray[0].OrganName;
        }

        let IOLStatusArray = $filter('filter')($scope.IOLStatusArray, { 'Id': $scope.ImplantsObj.StatusId }, true);
        if (IOLStatusArray.length > 0) {
            $scope.ImplantsObj.StatusName = IOLStatusArray[0].Name;
        }

        if ($scope.IntraOpObj.OthersDetailsArray.length > 0) {
            $scope.ImplantsObj.IolConsumeId = $scope.ImplantsObj.IolConsumeId || 0;
            if ($scope.ImplantsObj.IolConsumeId != 0) {
                let tempArray = $filter('filter')($scope.IntraOpObj.OthersDetailsArray, { 'IolConsumeId': $scope.ImplantsObj.IolConsumeId }, true);
                if (tempArray.length > 0) {
                    let index = $scope.IntraOpObj.OthersDetailsArray.findIndex((x) => x.IolConsumeId == item.IolConsumeId);
                    if (index > -1) {
                        $scope.IntraOpObj.OthersDetailsArray[index].ItemMasterId = $scope.ImplantsObj.ItemMasterId || null;
                        $scope.IntraOpObj.OthersDetailsArray[index].OrganizationItemId = $scope.ImplantsObj.OrganizationItemId || null;
                        $scope.IntraOpObj.OthersDetailsArray[index].SubCategoryId = $scope.ImplantsObj.SubCategoryId || null;
                        $scope.IntraOpObj.OthersDetailsArray[index].SubCategoryName = $scope.ImplantsObj.SubCategoryName || "";
                        $scope.IntraOpObj.OthersDetailsArray[index].ImplantName = $scope.ImplantsObj.ImplantName || "";

                        $scope.IntraOpObj.OthersDetailsArray[index].StatusId = $scope.ImplantsObj.StatusId || null;
                        $scope.IntraOpObj.OthersDetailsArray[index].StatusName = $scope.ImplantsObj.StatusName || "";
                        $scope.IntraOpObj.OthersDetailsArray[index].SerialNumber = $scope.ImplantsObj.SerialNumber || "";
                        $scope.IntraOpObj.OthersDetailsArray[index].ManufacturerId = $scope.ImplantsObj.ManufacturerId || null;
                        $scope.IntraOpObj.OthersDetailsArray[index].Manufacturer = $scope.ImplantsObj.Manufacturer || null;
                        $scope.IntraOpObj.OthersDetailsArray[index].Remarks = $scope.ImplantsObj.Remarks || "";
                        $scope.IntraOpObj.OthersDetailsArray[index].DeleteInd = $scope.ImplantsObj.DeleteInd || "";
                        $scope.IntraOpObj.OthersDetailsArray[index].OrganId = $scope.ImplantsObj.OrganId || null;
                        $scope.IntraOpObj.OthersDetailsArray[index].OrganName = $scope.ImplantsObj.OrganName || "";
                    }
                } else if (tempArray == 0) {
                    $scope.IntraOpObj.OthersDetailsArray.push($scope.ImplantsObj);
                }
            } else {
                $scope.IntraOpObj.OthersDetailsArray.push($scope.ImplantsObj);
            }
        } else {
            $scope.IntraOpObj.OthersDetailsArray.push($scope.ImplantsObj);
        }

        $scope.ShowImplants = '+ Add New Item';
        $scope.ImplantsObj = angular.copy($scope.GetImplants());
        type = type || "";
        if (type != "") {
            $scope.IntraOpObj.IsAddNewIOL = false;
        }
    }

