    $scope.$on("SummaryNavSubEvent", function (event, data) {
        if (data == 0) {
            $scope.ChangeTab(9);
        } else if (data == 1) {
            $scope.ChangeTab(2);
        } else if (data == 2) {
            $scope.init();
        } else if (data == 3) {
            $scope.ChangeTab(4);
        } else if (data == 4) {
            $scope.ChangeTab(11);
        } else if (data == 5) {
            $scope.ChangeTab(13);
        }

    });
