            $scope.Maskvalue = false;
            $scope.IntraOpObj.OxygenType = Type;
            $scope.IsEndotrachealTube = false;
            $scope.IsLMA = false;
            $scope.IntraOpObj.MaskValue = null;
            $scope.IntraOpObj.LMANotes = "";
            $scope.IntraOpObj.EndotrachealTubeNotes = "";
