    $scope.SaveComplicationsTemplateName = function () {

        if ($scope.IntraOpObj.Complications == '') {
            alertify.error("Please Enter Complications!");
            return;
        }
        $scope.IntraOpObj.SurgeonComplicationsTemplateName = $scope.IntraOpObj.SurgeonComplicationsTemplateName || "";
        if ($scope.IntraOpObj.SurgeonComplicationsTemplateName === "") {
            alertify.error("Please enter template name!");
            return false;
        } else {
            let templateReq = {
                "UserId": $scope.UserId || "",
                "HospitalId": $scope.HospitalId || "",
                "TemplateId": 0,
                "TemplateName": $scope.IntraOpObj.SurgeonComplicationsTemplateName || "",
                "DeleteInd": "N",
                "TemplateNotes": [],
                "TypeId": '2',
                "TypeName": 'Complications',
                "RoleId": $scope.RoleId
            };


            templateReq.TemplateNotes = $scope.IntraOpObj.Complications || "";
            /*console.log(templateReq);*/
            eHnoteSurgeryService.AddUpdateIntraOpTemplates(templateReq).then(function (resp) {
                if (resp.data.Status === "Success") {
                    alertify.success("Template saved successfully!");
                    $scope.GetPreOpMedicineCheckListTemplates();
                    $scope.isOpenComplicationsPopOver = false;
                    $scope.IntraOpObj.SurgeonComplicationsTemplateName = '';
                    //  $uibModalInstance.close();
                }
                if (resp.data.Status === "Failure") {
                    alertify.error('TemplateName Already Exists')
                }
            }, function (err) {
                console.log(err);
            });

        }

    };


