    $scope.Clearvalues = function (item) {
        alertify.confirm("<b class='txt-centre'>Confirm!</b><h4 class='txt-body-centre'>Are You Sure Want to Clear? </h4>", function () {
            if ($scope.AnesthetistVitals.length > 0) {
                angular.forEach($scope.AnesthetistVitals, function (Aitem) {
                    if (Aitem.VitalReadingList.length > 0) {
                        let temparray = $filter("filter")(Aitem.VitalReadingList, function (kitem, index) { return kitem.VitalSlotTime == item.time });
                        if (temparray.length > 0) {
                            temparray[0].Value = '';
                        }
                    }
                });
                $scope.$digest();
            }

        }, function () {
            return;
        });

    }
    $scope.DeleteVitalvalues = function (item) {
        alertify.confirm("<b class='txt-centre'>Confirm!</b><h4 class='txt-body-centre'>Are You Sure Want to Delete? </h4>", function () {
            if ($scope.AnesthetistVitals.length > 0) {
                angular.forEach($scope.AnesthetistVitals, function (Aitem) {
                    let temparray = $filter("filter")(Aitem.VitalReadingList, function (kitem, index) { return kitem.VitalSlotTime == item.time && kitem.DeleteInd == 'N' }) || [];
                    if (temparray.length > 0) {
                        temparray[0].IntraOPAnesthesiaVitalsId = temparray[0].IntraOPAnesthesiaVitalsId || 0;
                        if (temparray[0].IntraOPAnesthesiaVitalsId != 0) {
                            temparray[0].DeleteInd = 'Y';
                        } else {
                            //  let temparray = $filter("filter")(Aitem.VitalReadingList, function (kitem, index) { return kitem.VitalSlotTime == item.time && kitem.DeleteInd == 'N' }) || [];
                            let index = Aitem.VitalReadingList.findIndex(vital => vital.VitalSlotTime === item.time && vital.DeleteInd == 'N');
                            if (index !== -1) {
                                Aitem.VitalReadingList.splice(index, 1);
                            }
                        }
                    }

                })
            }

            if ($scope.NewTimeSlots.length > 0) {
                let index = $scope.NewTimeSlots.findIndex(vital => vital.time == item.time);
                if (index !== -1) {
                    $scope.NewTimeSlots.splice(index, 1);
                }

                // make lastbutoneIND false for all objects first before making it true for second from last object
                if ($scope.NewTimeSlots.length > 0) {
                    $scope.NewTimeSlots.forEach((x) => x.lastbutoneIND = false);
                }

                if ($scope.NewTimeSlots.length == 2 || $scope.NewTimeSlots.length > 2) {
                    $scope.NewTimeSlots[$scope.NewTimeSlots.length - 2].lastbutoneIND = true;
                }

                let filteredData = $filter('orderBy')($scope.NewTimeSlots, 'counter');
                if (filteredData.length > 0) {
                    $scope.IntraOpObj.InTime = filteredData[0].NewTime;
                    $scope.IntraOpObj.OutTime = filteredData[filteredData.length - 1].NewTime;
                    //$scope.IntraOpObj.NurseActionobj.HallEntranceEndTime = filteredData[filteredData.length - 1].NewTime;
                    //$scope.IntraOpObj.NurseActionobj.SurgeryEndTime = filteredData[filteredData.length - 1].NewTime;
                    /*$scope.IntraOpObj.NurseActionobj.AnesthesiaEndTime = filteredData[filteredData.length - 1].NewTime;*/
                    $scope.IntraOpObj.NurseActionobj.HandOffTime = filteredData[filteredData.length - 1].NewTime;
                    $scope.IntraOpObj.HandOffTime = filteredData[filteredData.length - 1].NewTime;
                }
            }


            if ($scope.NewTimeSlots.length === 0) {
                $scope.IntraOpObj.InTime = "";
                $scope.IntraOpObj.OutTime = "";
                //$scope.IntraOpObj.NurseActionobj.HallEntranceEndTime = "";
                //$scope.IntraOpObj.NurseActionobj.SurgeryEndTime = "";
                /*$scope.IntraOpObj.NurseActionobj.AnesthesiaEndTime = "";*/
                $scope.IntraOpObj.NurseActionobj.HandOffTime = "";
            }
            $scope.$digest();
        }, function () {
            return;
        });

    };

    $scope.getSerialNumbers = function (val) {
        val = val || "";
        if (val == "") {
            return;
        }

        let req = {
            "OrganizationId": $scope.HospitalId,
            "BarCode": val
        }

        return eHnoteSurgeryService.getSerialNumbersForImplants(req).then(function (resp) {
            //return resp.data.rows
            if (resp.data.rows.length > 0) {
                $scope.ImplantsObj.ShowAddNewBtn = false;
                return resp.data.rows.map(function (item) {
                    return item;
                });
            } else {
                $scope.ImplantsObj.ShowAddNewBtn = true;
            }

        }, function () {

        });
    };

    $scope.OnSelectSerialNumber = function (obj) {

        obj = obj || "";

        if (obj != "") {
            if (obj.IsConsumed) {
                $scope.ImplantsObj.SelectedObject = "";
                //let errorMsg = `Iol is already ${obj.SerialNoStatus}`;
                alertify.error("Iol is already consumed!");
                return;
            }
            // Return stock
            if (obj.SerialNoStatus == "Return") {
                $scope.ImplantsObj.SelectedObject = "";
                alertify.error("This Item is already Returned !");
                return;
            }

            if (obj.SerialNoStatus == "Delete") {
                $scope.ImplantsObj.SelectedObject = "";
                alertify.error("This Item is already Deleted !");
                return;
            }

            if (obj.SerialNoStatus == "Contaminated") {
                $scope.ImplantsObj.SelectedObject = "";
                alertify.error("IOL is Contaminated !");
                return;
            }

            if (obj.SerialNoStatus == "Damaged") {
                $scope.ImplantsObj.SelectedObject = "";
                alertify.error(" IOL is Damaged !");
                return;
            }

            if ($scope.ImplantsDetailsArray.length > 0) {
                let tempArray = $filter('filter')($scope.ImplantsDetailsArray, { 'SerialNumber': obj.BarCode, 'DeleteInd': 'N' }, true);
                if (tempArray.length > 0) {
                    $scope.ImplantsObj.SelectedObject = "";
                    alertify.error("IOL already added!");
                    return;
                }
            }

            let implantsDetails = angular.copy(obj);

            $scope.ImplantsObj.IsDisabled = true;
            $scope.ImplantsObj.IsIolSelected = true;

            $scope.ImplantsObj.ItemMasterId = obj.ItemMasterId;
            $scope.ImplantsObj.ImplantName = obj.ItemName;
            $scope.ImplantsObj.DipoterId = implantsDetails.DipoterId;
            $scope.ImplantsObj.ManufacturerId = implantsDetails.ManufacturerId;
            $scope.ImplantsObj.LensTypeId = implantsDetails.LensId;
            $scope.ImplantsObj.ModelId = implantsDetails.IolModelId;
            $scope.ImplantsObj.ModelNumber = implantsDetails.ModelNumber || "";
            $scope.ImplantsObj.StockDetailId = implantsDetails.StockDetailId;
            $scope.ImplantsObj.OrganizationItemId = implantsDetails.OrganizationItemId;
            $scope.ImplantsObj.ChildMasterId = implantsDetails.ChildMasterId;
            $scope.ImplantsObj.SerialNumber = implantsDetails.BarCode;
            $scope.ImplantsObj.BarCodeId = implantsDetails.BarCodeId;
            $scope.ImplantsObj.BarCodeDetailId = implantsDetails.BarCodeDetailId;
            $scope.ImplantsObj.StatusId = 3; // by default show option 'consumed'

            $scope.ImplantsObj.SelectedObject = "";
        }
    };

    $scope.OnChangeSerialNumber = function (val) {
        val = val || "";
        if (val == "") {
            $scope.IntraOpObj.ShowIolList = false;
        }
    };

