    $scope.AddNewIOLOrganizationItem = function (obj) {

        if (obj.ImplantName == "") {
            alertify.error("Please add implant name!");
            return;
        }

        obj.LensTypeId = obj.LensTypeId || null;
        if (obj.LensTypeId == null) {
            alertify.error("Please select Lens type!");
            return;
        }

        obj.ManufacturerId = obj.ManufacturerId || null;
        if (obj.ManufacturerId == null) {
            alertify.error("Please select manufacturer!");
            return;
        }

        obj.ModelNumber = obj.ModelNumber || "";
        if (obj.ModelNumber == "") {
            alertify.error("Please add model number!");
            return;
        }

        obj.DipoterId = obj.DipoterId || null;
        if (obj.DipoterId == null) {
            alertify.error("Please select power!");
            return;
        }

        obj.StatusId = obj.StatusId || null;
        if (obj.StatusId == null) {
            alertify.error("Please select status!");
            return;
        }

        let req = {
            "ItemMasterId": 0,
            "UserId": $scope.UserId,
            "OrganizationId": $scope.HospitalId,
            "ParentOrganizationId": $scope.ParenthospitalId,
            "ChildMasterId": obj.ChildMasterId || null,
            "OrganizationItemId": obj.OrganizationItemId || null,
            "SerialNumber": obj.SerialNumber || "",
            "CategoryId": 7,
            "SubCategoryId": 3,
            "ItemName": obj.ImplantName,
            "LensTypeId": obj.LensTypeId,
            "ManufacturerId": obj.ManufacturerId || null,
            "IolModelId": obj.ModelId || null,
            "DipoterId": obj.DipoterId || null,
            "BatchNumber": obj.BatchNumber || "",
            "DeleteInd": "N",
            "ModelNumber": obj.ModelNumber || ""
        };

        eHnoteSurgeryService.AddUpdateIolOrganizationItem(req).then(function (resp) {

            if (resp.data.Status == "Success") {
                if (resp.data.rows.length > 0) {
                    alertify.success("Iol Implant successfully added!");
                    let respObj = resp.data.rows[0];

                    $scope.ImplantsObj.ModelId = respObj.IolModelId || null;
                    $scope.ImplantsObj.ModelName = respObj.ModelName || "";

                    $scope.ImplantsObj.ItemMasterId = respObj.ItemMasterId || null;
                    $scope.ImplantsObj.OrganizationItemId = respObj.OrganizationItemId || null;
                    $scope.ImplantsObj.StockDetailId = respObj.StockDetailId || null;
                    $scope.ImplantsObj.ChildMasterId = respObj.ChildMasterId || null;
                    $scope.ImplantsObj.BarCodeDetailId = respObj.BarCodeDetailId || null;
                    $scope.ImplantsObj.BarCodeId = respObj.BarCodeId || null;
                    $scope.ImplantsObj.IolConsumeId = respObj.IolConsumeId || null;

                    $scope.AddIOLImplant($scope.ImplantsObj, "NewIol");
                }
            } else {
                alertify.error("Add IOl service failed!");
                return;
            }


        }, function (err) {

        });

    };
