    $scope.OnChangePreProcedureNotes = function () {
        if ($scope.IntraOpObj.PatientStableSurgery) {
            let statement1 = "Patient is stable for surgery.";
            let statement2 = "Pre-operative workup was found adequate.";
            if ($scope.IntraOpObj.AdequatePreoperativeWorkup) {
                $scope.IntraOpObj.PreProcedureNotes = statement1 + " " + statement2;
            } else {
                $scope.IntraOpObj.PreProcedureNotes = statement1;
            }
        } else if ($scope.IntraOpObj.AdequatePreoperativeWorkup) {
            $scope.IntraOpObj.PreProcedureNotes = "Pre-operative workup was found adequate.";
        } else {
            $scope.IntraOpObj.PreProcedureNotes = "";
        }
    };

    $scope.IntraOpNurseSignOffUserId = 0;
    $scope.IntraOpNurseSignOff = function (type) {
        var i = 0;
        // Task 13 - medication timings must be validated with the Given By passcode before signing off.
        if (DropTimingGivenByService.GetNotValidatedCountInOrders($scope.IntraOpObj.OrderDetails, 4, 'IntraOpMedications') > 0) {
            alertify.error("Please validate Given By password for Medications!");
            return false;
        }
        // Task 13 - custom orders marked Done need the Given By passcode too.
        if (DropTimingGivenByService.GetNotValidatedGeneralOrdersInOrders($scope.IntraOpObj.OrderDetails, 4) > 0) {
            alertify.error("Please validate Given By password for Custom Orders!");
            return false;
        }
        angular.forEach($scope.IntraOpObj.IntraOpMedications, function (item) {
            /*if (item.AscMedicationId == 0) {*/
            if (item.DropTimings.length > 0) {
                let tempArray = $filter('filter')(item.DropTimings, { 'GivenBy': null }, true);
                if (tempArray.length > 0) {
                    i++
                }
            }
            /* }*/
        });
        if (i !== 0) {
            alertify.error("Plese select Givenby for Medications!");
            return false;
        }
        var Type = type || "";
        let obj = {
            "Screen": "IntraOp",
            "Type": Type,
            "UserType": "Nurse",
            "allUserList": angular.copy($scope.allUserList),
        };

        let signmodalInstance = $uibModal.open({
            "templateUrl": "templates/consultation/SignOffPasswordNew.html",
            "controller": "UsSignOffPasswordPopupCtrl",
            "size": "md",
            "backdrop": "static",
            "keyboard": false,
            "resolve": {
                "obj": function () { return obj; }
            }
        });
        signmodalInstance.result.then(function (resp) {
            $scope.IntraOpNurseSignOffUserId = resp.DoctorId || 0;
            $scope.SaveIntraOpNurseChartData(Type);
        }, function (data) {

        });
    }
    $scope.IntraOpAnesthesiaSignOffUserId = 0;
    $scope.IntraOpAnesthesiaSignOff = function (type) {

        // for Getting Alert When Try to Signoff  in medication
        var i = 0;
        var givenByNotValidated = 0;
        let K = 0;
        let FinalOrderDetails = [];
        FinalOrderDetails = $filter('filter')($scope.IntraOpObj.OrderDetails, { 'MedTypeId': 3 }, true) || [];
        if (FinalOrderDetails.length > 0) {
            angular.forEach(FinalOrderDetails, function (Mitem) {
                Mitem.IsOrderReviewed = Mitem.IsOrderReviewed || false;
                Mitem.ReviewedBy = Mitem.ReviewedBy || null;
                if (Mitem.ReviewedBy != null && Mitem.IsOrderReviewed == false) {
                    if (Mitem.ReviewedByPassword == '') {
                        K++;
                    }
                }
                if (Mitem.IntraOpMedications.length > 0) {
                    angular.forEach(Mitem.IntraOpMedications, function (item) {
                        if (item.DropTimings.length > 0) {
                            let tempArray = $filter('filter')(item.DropTimings, { 'GivenBy': null }, true);
                            if (tempArray.length > 0) {
                                i++;
                            }
                            // Task 13 - every timing must be validated with the Given By passcode before saving.
                            givenByNotValidated += DropTimingGivenByService.GetNotValidatedCount(item.DropTimings);
                        };
                    });
                }
            });
        }
        if (K !== 0) {
            alertify.error("Plese Enter Password");
            return false;
        }
        if (i !== 0) {
            alertify.error("Plese select Givenby for Medications!");
            return false;
        }
        if (givenByNotValidated !== 0) {
            alertify.error("Please validate Given By password for Medications!");
            return false;
        }

        function checkEmptyValuesForSlotTime(vitalData, slotTime) {
            const readings = vitalData.flatMap(item => item.VitalReadingList);
            const readingsForSlotTime = readings.filter(reading => reading.VitalSlotTime === slotTime && reading.DeleteInd == "N");

            return readingsForSlotTime.every(reading => reading.Value === "");
        }

        let vitalscounter = 0;

        $scope.NewTimeSlots.forEach(slot => {
            if (checkEmptyValuesForSlotTime($scope.AnesthetistVitals, slot.time)) {
                vitalscounter++;
            }
        });

        if (vitalscounter > 0) {
            alertify.error("Please enter vitals!");
            return;
        }

        var Type = type || "";
        let obj = {
            "Screen": "IntraOp",
            "Type": Type,
            "UserType": "Anesthesia",
            "allUserList": angular.copy($scope.allUserList),
        };

        let signmodalInstance = $uibModal.open({
            "templateUrl": "templates/consultation/SignOffPasswordNew.html",
            "controller": "UsSignOffPasswordPopupCtrl",
            "size": "md",
            "backdrop": "static",
            "keyboard": false,
            "resolve": {
                "obj": function () { return obj; }
            }
        });
        signmodalInstance.result.then(function (resp) {
            //$scope.SaveIntraOpAnesthesiaChartData(Type);
            $scope.IntraOpAnesthesiaSignOffUserId = resp.DoctorId || 0;

            $scope.SaveIntraOpAnesthesiaChartDataNew(Type);

        }, function (data) {

        });
    }

