    function compareCheckList(oldArr, newArr, Id) {
        Id = Id || 0;
        oldArr = (oldArr || []).filter(x => x.DeleteInd === "N");
        newArr = (newArr || []).filter(x => x.DeleteInd === "N");

        let oldBlockArr = [];
        let newBlockArr = [];

        newArr.forEach(nItem => {
            let oItem = oldArr.find(x => x.OrganizationCheckListId == nItem.OrganizationCheckListId);

            /* -------- NEW BLOCK -------- */
            let newBlock = "";
            if (nItem.IsChecked) {
                newBlock += `${nItem.CheckListName}`;

                if (nItem.SubCheckList && nItem.SubCheckList.length > 0) {
                    nItem.SubCheckList
                        .filter(c => c.IsChecked && c.DeleteInd === "N")
                        .forEach(c => {
                            newBlock += `\n  • ${c.SubCheckListName}`;
                        });
                }
            }

            /* -------- OLD BLOCK -------- */
            let oldBlock = "";
            if (oItem) {
                oldBlock += `${oItem.CheckListName}`;

                if (oItem.SubCheckList && oItem.SubCheckList.length > 0) {
                    oItem.SubCheckList
                        .filter(c => c.IsChecked && c.DeleteInd === "N")
                        .forEach(c => {
                            oldBlock += `\n  • ${c.SubCheckListName}`;
                        });
                }
            }

            if (oldBlock.trim() !== newBlock.trim()) {
                if (oldBlock.trim()) oldBlockArr.push(oldBlock.trim());
                if (newBlock.trim()) newBlockArr.push(newBlock.trim());
            }
        });
        if (Id==8) {
            return {
                oldText: oldBlockArr.length ? "Before Incision :\n" + oldBlockArr.join("\n\n") : "",
                newText: newBlockArr.length ? "Before Incision :\n" + newBlockArr.join("\n\n") : ""
            };
        }
        if (Id == 9) {
            return {
                oldText: oldBlockArr.length ? "Before leaving OR :\n" + oldBlockArr.join("\n\n") : "",
                newText: newBlockArr.length ? "Before leaving OR :\n" + newBlockArr.join("\n\n") : ""
            };
        }
    }

