    $scope.findDifferences = function (savedArray, editedArray) {
        var differences = [];
        /* var maxLength = Math.max(arr1.length, arr2.length);*/

        angular.forEach(savedArray, function (item) {
            item.ChecklistDate = item.ChecklistDate || null;
            item.Remarks = item.Remarks || '';

            var edited = editedArray.filter(function (eitem) {
                eitem.Remarks = eitem.Remarks || '';

                return ((eitem.CheckListCategoryId == item.CheckListCategoryId) && (item.CheckListId == eitem.CheckListId) && (item.Value == eitem.Value) && (item.Remarks == eitem.Remarks) && (item.DeleteInd == eitem.DeleteInd));
            }) || [];


            if (edited.length == 0) {
                differences.push({
                    CheckListCategoryId: item.CheckListCategoryId,
                    CheckListId: item.CheckListId,
                    CheckListName: item.CheckListName,
                    savedValue: item.Value,
                    DeleteInd: item.DeleteInd,
                    Remarks: item.Remarks,
                    ChecklistDate: item.ChecklistDate,
                });
                /*count++;*/
            }

        });
  

        return differences;
    };

    function buildVitalsLines(arr) {
        let vitalsByTime = {};

        arr.forEach(v => {
            if (v.DeleteInd !== 'N') return;

            let val = (v.Value !== null && v.Value !== undefined)
                ? String(v.Value).trim() : '';
            if (val === '') return;

            let timeKey = v.VitalSlotTime;
            if (!timeKey) return;

            if (!vitalsByTime[timeKey]) vitalsByTime[timeKey] = [];
            vitalsByTime[timeKey].push({ name: v.VitalName, display: `${v.VitalName} : ${val}` });
        });

        return Object.keys(vitalsByTime)
            .sort()
            .map(time => {
                let sorted = vitalsByTime[time]
                    .sort((a, b) => a.name.localeCompare(b.name))
                    .map(x => x.display);

                let displayTime = moment(time, "HH:mm").format("hh:mm A");
                return `VitalTime : ${displayTime}, ${sorted.join(', ')}`;
            });
    }

    function getOxygenText(status, qty, ettNotes, lmaNotes) {
        if (!status) return '';
        let s = parseInt(status, 10);
        if (s === 1) return `Oxygen : Mask : ${qty || ''}`;
        if (s === 2) return `Oxygen : N/C : ${qty || ''}`;
        if (s === 3) return `Oxygen : Endotracheal Tube : ${ettNotes || ''}`;
        if (s === 4) return `Oxygen : LMA : ${lmaNotes || ''}`;
        return '';
    }

    function compareAnestialVitals(newVitals, oldVitals) {

        // ── DELETE case ───────────────────────────────────────────────────────────
        let deletedVitals = newVitals.filter(v => {
            if (v.DeleteInd !== 'Y') return false;
            if (!v.IntraOPAnesthesiaVitalsId) return false;
            return oldVitals.some(o => o.IntraOPAnesthesiaVitalsId === v.IntraOPAnesthesiaVitalsId);
        });

        let deletedIds = new Set(deletedVitals.map(v => v.IntraOPAnesthesiaVitalsId));

        if (deletedVitals.length > 0) {
            let deletedByTime = {};
            deletedVitals.forEach(v => {
                let timeKey = v.VitalSlotTime;
                if (!timeKey || !v.Value) return;
                if (!deletedByTime[timeKey]) deletedByTime[timeKey] = [];
                deletedByTime[timeKey].push(`${v.VitalName} : ${v.Value}`);
            });

            let deletedLines = Object.keys(deletedByTime)
                .sort()
                .map(time => {
                    let displayTime = moment(time, "HH:mm").format("hh:mm A");
                    return `VitalTime : ${displayTime}, ${deletedByTime[time].join(', ')}`;
                });

            let OldValue = deletedLines.join('\n');
            if (OldValue) {
                $scope.LogObj.LogArray.push({
                    LogId: 0,
                    ModuleId: 2,
                    ModuleName: 'ASC',
                    SubModuleId: 10,
                    SubModuleName: 'Intra-Op',
                    ScreenType: 'Anesthesia Vitals',
                    ActionType: 'Deleted',
                    OldActionDescription: OldValue,
                    NewActionDescription: '',
                    ActionDateTime: $filter('date')(new Date(), 'yyyy-MM-dd HH:mm:ss'),
                });
            }
        }


        let activeNew = newVitals.filter(v =>
            v.DeleteInd !== 'Y' && !deletedIds.has(v.IntraOPAnesthesiaVitalsId)
        );
        let activeOld = oldVitals.filter(v =>
            v.DeleteInd !== 'Y' && !deletedIds.has(v.IntraOPAnesthesiaVitalsId)
        );


        // ── ROW-BY-ROW DIFF ───────────────────────────────────────────────────────
        let changedOldRows = []; // rows that existed before but value changed
        let changedNewRows = []; // same rows with new values
        let addedRows = []; // rows in new but not in old
        let removedRows = []; // rows in old but not in new

        // 1. Find changed and added rows by iterating newVitals
        activeNew.forEach(newRow => {
            let val = (newRow.Value !== null && newRow.Value !== undefined)
                ? String(newRow.Value).trim() : '';
            //if (val === '') return; // skip empty/default rows — user never typed anything

            if (val === '') {
                // ✅ NEW: if old row had a value, treat as cleared/removed
                if (newRow.IntraOPAnesthesiaVitalsId) {
                    let oldRow = activeOld.find(o =>
                        o.IntraOPAnesthesiaVitalsId === newRow.IntraOPAnesthesiaVitalsId
                    );
                    let oldVal = oldRow && (oldRow.Value !== null && oldRow.Value !== undefined)
                        ? String(oldRow.Value).trim() : '';
                    if (oldRow && oldVal !== '') {
                        removedRows.push(oldRow); // log it as removed
                    }
                }
                return;
            }

            if (!newRow.IntraOPAnesthesiaVitalsId) {
                // Brand new row — no ID means never saved before
                addedRows.push(newRow);
                return;
            }

            // Find matching old row by ID
            let oldRow = activeOld.find(o =>
                o.IntraOPAnesthesiaVitalsId === newRow.IntraOPAnesthesiaVitalsId
            );

            if (!oldRow) {
                // Exists in new but not in old — treat as added
                addedRows.push(newRow);
                return;
            }

            // Compare value and time slot
            let oldVal = (oldRow.Value !== null && oldRow.Value !== undefined)
                ? String(oldRow.Value).trim() : '';
            let oldTime = oldRow.VitalSlotTime || '';
            let newTime = newRow.VitalSlotTime || '';
            let oldVName = oldRow.VitalName || '';
            let newVName = newRow.VitalName || '';

            if (oldVal !== val || oldTime !== newTime || oldVName !== newVName) {
                // Something changed on this row
                changedOldRows.push(oldRow);
                changedNewRows.push(newRow);
            }
            // If nothing changed — skip entirely (this was the bug)
        });

        // 2. Find removed rows — in old but completely missing from new
        activeOld.forEach(oldRow => {
            let stillExists = activeNew.find(n =>
                n.IntraOPAnesthesiaVitalsId === oldRow.IntraOPAnesthesiaVitalsId
            );
            if (!stillExists) {
                removedRows.push(oldRow);
            }
        });

        // ── Build old/new lines from ONLY the diffed rows ─────────────────────────
        let oldLines = buildVitalsLines([...changedOldRows, ...removedRows]);
        let newLines = buildVitalsLines([...changedNewRows, ...addedRows]);

        // ── Scalar field diffs (oxygen, notes) ───────────────────────────────────
        let oldExtras = [];
        let newExtras = [];

        let oldOxy = getOxygenText(
            $scope.LogObj.OxygenStatus,
            $scope.LogObj.OxygenQuantity || '',
            $scope.LogObj.EndotrachealTubeNotes || '',
            $scope.LogObj.LMANotes || ''
        );
        let newOxy = getOxygenText(
            $scope.IntraOpObj.OxygenStatus,
            $scope.IntraOpObj.OxygenQuantity || '',
            $scope.IntraOpObj.EndotrachealTubeNotes || '',
            $scope.IntraOpObj.LMANotes || ''
        );
        if (oldOxy !== newOxy) {
            if (oldOxy) oldExtras.push(oldOxy);
            if (newOxy) newExtras.push(newOxy);
        }

        let oldIntake = $scope.LogObj.IntakeValue || '';
        let newIntake = $scope.IntraOpObj.IntakeValue || '';
        if (oldIntake !== newIntake) {
            if (oldIntake) oldExtras.push(`Intake Notes : ${oldIntake}`);
            if (newIntake) newExtras.push(`Intake Notes : ${newIntake}`);
        }

        let oldOutput = $scope.LogObj.OutputValue || '';
        let newOutput = $scope.IntraOpObj.OutputValue || '';
        if (oldOutput !== newOutput) {
            if (oldOutput) oldExtras.push(`Output Notes : ${oldOutput}`);
            if (newOutput) newExtras.push(`Output Notes : ${newOutput}`);
        }

        let oldEBL = $scope.LogObj.EBLValue || '';
        let newEBL = $scope.IntraOpObj.EBLValue || '';
        if (oldEBL !== newEBL) {
            if (oldEBL) oldExtras.push(`EBL Notes : ${oldEBL}`);
            if (newEBL) newExtras.push(`EBL Notes : ${newEBL}`);
        }

        if (oldExtras.length) oldLines.push(oldExtras.join(', '));
        if (newExtras.length) newLines.push(newExtras.join(', '));

        let OldValue = oldLines.join('\n');
        let NewValue = newLines.join('\n');

        // ── Only log if something actually changed ────────────────────────────────
        if (OldValue || NewValue) {
            $scope.LogObj.LogArray.push({
                LogId: 0,
                ModuleId: 2,
                ModuleName: 'ASC',
                SubModuleId: 10,
                SubModuleName: 'Intra-Op',
                ScreenType: 'Anesthesia Vitals',
                ActionType: 'Edited',
                OldActionDescription: OldValue,
                NewActionDescription: NewValue,
                ActionDateTime: $filter('date')(new Date(), 'yyyy-MM-dd HH:mm:ss'),
            });
        }
    }

