            let handOffTime = new Date();
            let timeParts = $scope.IntraOpObj.HandOffTime.match(/(\d+):(\d+)\s?(AM|PM)/i);

            if (timeParts) {
                let hours = parseInt(timeParts[1]);
                let minutes = parseInt(timeParts[2]);
                let meridian = timeParts[3].toUpperCase();

                if (meridian === "PM" && hours < 12) hours += 12;
                if (meridian === "AM" && hours === 12) hours = 0;

                handOffTime.setHours(hours);
                handOffTime.setMinutes(minutes);
                handOffTime.setSeconds(0);
                handOffTime.setMilliseconds(0);
            }
