                var start = new Date(todayString + ' ' + $scope.IntraOpObj.DischargeSignOffStartTime);

                // Add dischargeMinutes to start time
                var end = new Date(start.getTime() + dischargeMinutes * 60 * 1000);

                // Format back to readable "h:mm A" (like 5:40 AM)
                var options = { hour: 'numeric', minute: '2-digit', hour12: true };
                var formattedEnd = end.toLocaleTimeString('en-US', options);

