    $scope.ChangeFallRisKChecklist = function (bool, MItem) {
        angular.forEach(MItem.OrganizationCheckListDetails, function (item) {
            item.IsChecked = false;
        });
        bool.IsChecked = true;
        MItem.IsChecked = true;
        MItem.Value = bool.Value || '';

        if (bool.CheckListId == 162 || bool.CheckListId == 163 || bool.CheckListId == 165) {
            if (bool.Value == "Yes") {
                MItem.Score = 25;
            } else {
                MItem.Score = 0;
            }
        } else {
            if (bool.CheckListId == 164) {
                if (bool.Value == 'Bed rest/nurse assist') {
                    MItem.Score = 0;
                } else if (bool.Value == 'Crutches/cane/walker') {
                    MItem.Score = 15;
                } else if (bool.Value == 'Furniture') {
                    MItem.Score = 30;
                } else { }
            }

            if (bool.CheckListId == 166) {
                if (bool.Value == 'Normal/bedrest/immobile') {
                    MItem.Score = 0;
                } else if (bool.Value == 'Weak') {
                    MItem.Score = 15;
                } else if (bool.Value == 'Impaired') {
                    MItem.Score = 30;
                } else { }
            }

            if (bool.CheckListId == 167) {
                if (bool.Value == 'Oriented to own ability') {
                    MItem.Score = 0;
                } else if (bool.Value == 'Forgets limitations') {
                    MItem.Score = 15;
                } else { }
            }
        }

        $scope.IntraOpObj.NurseActionobj.FallRiskAssessmentTotalScore = 0;
        angular.forEach($scope.IntraOpObj.AllIntraOpChecklistsArray, function (Titem) {
            if (Titem.CheckListId == 162 || Titem.CheckListId == 163 || Titem.CheckListId == 164 || Titem.CheckListId == 165 || Titem.CheckListId == 166 || Titem.CheckListId == 167) {
                Titem.Score = Titem.Score || 0;
                $scope.IntraOpObj.NurseActionobj.FallRiskAssessmentTotalScore += Titem.Score || 0;
            }
        });

        if ($scope.IntraOpObj.NurseActionobj.FallRiskAssessmentTotalScore <= 24) {
            $scope.IntraOpObj.NurseActionobj.FallRiskLevel = 'No Risk';
            $scope.IntraOpObj.NurseActionobj.ImplementedFallRiskProtocoltype = 'Good basic nursing care taken';
        } else if ($scope.IntraOpObj.NurseActionobj.FallRiskAssessmentTotalScore >= 25 && $scope.IntraOpObj.NurseActionobj.FallRiskAssessmentTotalScore <= 50) {
            $scope.IntraOpObj.NurseActionobj.FallRiskLevel = 'low Risk';
            $scope.IntraOpObj.NurseActionobj.ImplementedFallRiskProtocoltype = 'Implemented standard fall prevention interventions';
        } else if ($scope.IntraOpObj.NurseActionobj.FallRiskAssessmentTotalScore > 50) {
            $scope.IntraOpObj.NurseActionobj.FallRiskLevel = 'High Risk';
            $scope.IntraOpObj.NurseActionobj.ImplementedFallRiskProtocoltype = 'Implemeted high risk fall prevention interventions';
        }
    };

