    $scope.SaveIntraopCheckInChecklistTemplate = function (val) {


        $scope.IntraOpObj.CheckInChecklistTemplateName = $scope.IntraOpObj.CheckInChecklistTemplateName || "";
        if ($scope.IntraOpObj.CheckInChecklistTemplateName === "") {
            alertify.error("Please enter template name!");
            return false;
        }

        let templateReq = {
            "UserId": $scope.UserId,
            "HospitalId": $scope.HospitalId,
            "UserIntraOpCheckListTemplateId": 0,
            "TemplateName": $scope.IntraOpObj.CheckInChecklistTemplateName,
            "CheckListCategoryId": val,
            "DeleteInd": "N",
            "TemplateDetails": [],
        };
        let ChecklistArray = $filter('filter')($scope.IntraOpObj.AllIntraOpChecklistsArray, { 'CheckListCategoryId': val }, true);
        console.log(ChecklistArray);
        angular.forEach(ChecklistArray, function (item) {
            angular.forEach(item.OrganizationCheckListDetails, function (kitem) {
                if (kitem.IsChecked) {
                    let obj = {
                        "UserIntraOpCheckListTemplateDetailId": 0,
                        "UserIntraOpCheckListTemplateId": 0,
                        "CheckListId": kitem.CheckListId,
                        "OrganizationIntraOpCheckListId": kitem.OrganizationPreOpCheckListId,
                        "OrganizationIntraOpCheckListValueId": kitem.OrganizationPreOpCheckListValueId,
                        "DeleteInd": "N"
                    };
                    templateReq.TemplateDetails.push(obj);
                }
            });
        });
        console.log(templateReq);
        if (templateReq.TemplateDetails.length == 0) {
            alertify.error("Please Add atleast One Check list!");
            return false;

        }    
      
        eHnoteSurgeryService.AddUpdateIntraOpCheckListTemplates(templateReq).then(function (resp) {
            if (resp.data.status === "Success") {
                alertify.success("Template saved successfully!");
                $scope.GetIntraOpCheckListTemplates(26);
                $scope.IsOpenCheckinChecklist = false;
                $scope.IntraOpObj.CheckInChecklistTemplateName = '';              
            }
            if (resp.data.status === "Failure") {               
                alertify.error(resp.data.Message)
            }
        }, function (err) {          
            console.log(err);
        });
    };


