    $scope.OnSelectChecklistTemplate = function (obj, val) {  
        angular.forEach($scope.IntraOpObj.AllIntraOpChecklistsArray, function (Mitem) {
            angular.forEach(Mitem.OrganizationCheckListDetails, function (Msubitem) {
                Msubitem.IsChecked = false;
                Mitem.IsChecked = false;
            });
        });
        if (obj.TemplateDetails.length > 0) {
            angular.forEach(obj.TemplateDetails, function (item) {
                if ($scope.IntraOpObj.AllIntraOpChecklistsArray.length > 0) {

                    angular.forEach($scope.IntraOpObj.AllIntraOpChecklistsArray, function (Mitem) {
                        if (Mitem.CheckListId == item.CheckListId && Mitem.OrganizationCheckListDetails.length > 0) {
                            angular.forEach(Mitem.OrganizationCheckListDetails, function (Msubitem) {
                                // Msubitem.IsChecked = false;
                                if (Msubitem.OrganizationPreOpCheckListValueId == item.OrganizationIntraOpCheckListValueId) {
                                    Msubitem.IsChecked = true;
                                    Mitem.IsChecked = true;
                                    Mitem.Value = Msubitem.Value || '';
                                }
                            });
                        }

                    });
                }
            });
        }

    }

