    $scope.MedicationOrdersReviwedByLogs = function (item) {
        $scope.LogObj.LogArray = [];
        item.UserType = item.UserType || '';
        if (item.ReviewedBy != null || item.ReviewedByPassword != '') {
            let givenByUser = '';
            var ReviewedByArraylist = $filter("filter")($scope.allUserList, function (eitem) { return eitem.DoctorID == item.ReviewedBy });
            if (ReviewedByArraylist.length > 0) {
                givenByUser = angular.copy(ReviewedByArraylist[0].SecondUserFullName) +
                    (ReviewedByArraylist[0].LicenseNumber ? " Lic:" + angular.copy(ReviewedByArraylist[0].LicenseNumber) : "");
            }
            let ActionDescription = ''
            if (item.MedTypeId == 3) {
                ActionDescription = `Anesthesia Orders Reviewed By ${givenByUser} in Intra-Op ${item.UserType} For Appointment ID: ${$scope.cacheStorageItem.AppointmentId}`;
            } else if (item.MedTypeId == 4) {
                ActionDescription = `Surgeon Orders Reviewed By ${givenByUser} in Intra-Op ${item.UserType} For Appointment ID: ${$scope.cacheStorageItem.AppointmentId}`;
            }

            let obj = {
                "LogId": 0,
                "ModuleId": 2,
                "ModuleName": "ASC",
                "SubModuleId": 9,
                "SubModuleName": "Intra-Op",
                "ScreenType": "Intra-op Orders",
                "ActionType": "Added",
                "ActionDescription": ActionDescription,
                "ActionDateTime": $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss"),
            };
            $scope.LogObj.LogArray.push(obj);

            eHnoteSurgeryService.AddAuditLog($scope.LogObj).then(function (resp) {
                if (resp.data.status == "Success") {
                    console.log("Added");
                }
            })
        }
    };

    $scope.changeASCTemplate = function (val) {
        $scope.AscTemplateScreenObj.TemplateName = val.TemplateName || '';
        $scope.AscTemplateScreenObj.SurgeryTemplateId = val.UserSurgeryTemplateId || 0;
        if (val.OrgASCChecklist.length > 0) {
            let IntraOpOrgASCChecklist = $filter("filter")(val.OrgASCChecklist, function (item) {
                return item.CheckListModuleId == 2;
            }) || [];
            angular.forEach($scope.IntraOpObj.AllIntraOpChecklistsArray, function (item) {
                item.IsChecked = false;
                //item.DeleteInd = 'Y';          
                if (item.SubCheckList.length > 0) {
                    angular.forEach(item.SubCheckList, function (kitem) {
                        kitem.IsChecked = false;
                        kitem.PatientAscSubCheckListId = kitem.PatientAscSubCheckListId || null;
                        if (kitem.PatientAscSubCheckListId != null) {

                            kitem.DeleteInd = 'Y';
                        }
                    });
                }
                if (Array.isArray(item.AscMultiCheckValueArray)) {
                    angular.forEach(item.AscMultiCheckValueArray, function (jitem) {
                        jitem.IsChecked = false;
                        jitem.PatientMultiCheckListId = jitem.PatientMultiCheckListId || null;
                        if (jitem.PatientMultiCheckListId != null) {

                            jitem.DeleteInd = 'Y';
                        }
                    });
                }
                if (item.OrganizationCheckListDetails.length > 0) {
                    angular.forEach(item.OrganizationCheckListDetails, function (kitem) {
                        kitem.IsChecked = false;
                        kitem.PatientAscCheckListDetailId = kitem.PatientAscCheckListDetailId || null;
                        if (kitem.PatientAscCheckListDetailId != null || kitem.PatientMultiCheckListId != null || kitem.PatientAscSubCheckListId != null) {
                            kitem.DeleteInd = 'Y';
                        }
                    });
                }

            });
            if (IntraOpOrgASCChecklist.length > 0) {
                let TempAllIntraOpChecklistArray = [];
                const multiSelectCheckListIds = [178, 179, 180];

          

                angular.forEach(IntraOpOrgASCChecklist, function (item) {
                    angular.forEach($scope.IntraOpObj.AllIntraOpChecklistsArray, function (kitem) {
                        if (kitem.CheckListCategoryId === item.CheckListCategoryId &&
                            kitem.CheckListId === item.CheckListId) {

                            kitem.IsChecked = true;
                            kitem.Score = item.Score || 0;
                            kitem.Value = item.Value || '';
                            kitem.Remarks = item.Remarks || '';
                            kitem.intranotes1 = kitem.Remarks !== '';
                            kitem.PatientAscCheckListDetailId = kitem.PatientAscCheckListDetailId || null;
                            if (kitem.PatientAscCheckListDetailId !=null) {
                                kitem.DeleteInd = 'N';
                            }

                            // Special case: 180 with no multi-selects
                            if (item.CheckListId === 180 && (!item.AscMultiCheckValueArray || item.AscMultiCheckValueArray.length === 0)) {
                                kitem.IsChecked = false;
                                kitem.Value = '';
                            }

                            // SubChecklist
                            if (Array.isArray(item.SubCheckList)) {
                                angular.forEach(item.SubCheckList, function (jitem) {
                                    angular.forEach(kitem.SubCheckList, function (hitem) {
                                        if (hitem.SubCheckListId === jitem.SubCheckListId) {
                                            hitem.IsChecked = true;
                                            hitem.PatientAscSubCheckListId = hitem.PatientAscSubCheckListId || null;
                                            if (hitem.PatientAscSubCheckListId != null) {
                                                hitem.DeleteInd = 'N';
                                            }
                                        }
                                    });
                                });
                            }

                            // Multi-check logic
                            if (multiSelectCheckListIds.includes(item.CheckListId)) {
                                if (Array.isArray(item.AscMultiCheckValueArray)) {
                                    angular.forEach(item.AscMultiCheckValueArray, function (jitem) {
                                        angular.forEach(kitem.OrganizationCheckListDetails, function (hitem) {
                                            if (hitem.OrganizationPreOpCheckListValueId === jitem.OrganizationPreOpCheckListValueId) {
                                                hitem.IsChecked = true;
                                                hitem.PatientMultiCheckListId = hitem.PatientMultiCheckListId || null;
                                                if (hitem.PatientMultiCheckListId != null) {
                                                    hitem.DeleteInd = 'N';
                                                }
                                            }
                                        });
                                    });
                                }
                            } else {
                                angular.forEach(kitem.OrganizationCheckListDetails, function (Gitem) {
                                    Gitem.IsChecked = (item.Value === Gitem.Value);
                                    Gitem.PatientAscCheckListDetailId = Gitem.PatientAscCheckListDetailId || null;
                                    if (Gitem.IsChecked && Gitem.PatientAscCheckListDetailId != null) {
                                        Gitem.DeleteInd = 'N';
                                    }
                                        
                                });
                            }

                            TempAllIntraOpChecklistArray.push(angular.copy(kitem));
                        }
                    });
                });

                if ($scope.IntraOpObj.AllIntraOpChecklistsArray.length > 0) {
                    angular.forEach($scope.IntraOpObj.AllIntraOpChecklistsArray, function (Item) {
                        if (Item.CheckListId == 159 && Item.IsChecked) {
                            $scope.IntraOpObj.NurseActionobj.IsShowAnesthetistReviewByinFireRisk = true;
                        }
                        if (Item.CheckListId == 160 && Item.IsChecked) {
                            $scope.IntraOpObj.NurseActionobj.IsShowDoctorReviewByinFireRisk = true;
                        }
                    });
                }

                var TemparrayList = [];
                var TemparrayList = $filter("filter")($scope.IntraOpObj.AllIntraOpChecklistsArray, { 'CheckListCategoryId': 13, "IsChecked": true }, true);

                if (TemparrayList.length == 0 && $scope.IntraOpObj.NurseActionobj.HallEntranceStartTime == "" && $scope.IntraOpObj.NurseActionobj.PatientReceivedByName == "" && $scope.IntraOpObj.PatientStableSurgery == false && $scope.IntraOpObj.AdequatePreoperativeWorkup == false) {
                    $scope.IntraOpSummaryObj.IsIntraOpNurseIntraPreOpCallInd = false;
                } else {
                    $scope.IntraOpSummaryObj.IsIntraOpNurseIntraPreOpCallInd = true;
                }

                var anesthesiaIntraTemparrayList = [];
                var anesthesiaIntraTemparrayList = $filter("filter")($scope.IntraOpObj.AllIntraOpChecklistsArray, { 'CheckListCategoryId': 26, "IsChecked": true }, true);

                if (anesthesiaIntraTemparrayList.length == 0 ) {
                    $scope.IntraOpSummaryObj.IsIntraOpNurseIntraanesthesiaIntraTemparrayList = false;
                } else {
                    $scope.IntraOpSummaryObj.IsIntraOpNurseIntraanesthesiaIntraTemparrayList = true;
                }

            }
        }
        if (val.IntraOp != undefined && val.IntraOp.NurseActions != undefined) {
            $scope.IntraOpObj.NurseActionobj.IntraOPNurseTemplateActionId = val.IntraOp.NurseActions.IntraOPNurseTemplateActionId || 0;

            $scope.IntraOpObj.NurseActionobj.CleanContaminated = val.IntraOp.NurseActions.CleanContaminated || false;
            $scope.IntraOpObj.NurseActionobj.Cleansed = val.IntraOp.NurseActions.Cleansed || false;
            $scope.IntraOpObj.NurseActionobj.Contaminated = val.IntraOp.NurseActions.Contaminated || false;
            $scope.IntraOpObj.NurseActionobj.Dirty = val.IntraOp.NurseActions.Dirty || false;

        }

    }
    $scope.ASCTemplateSummury = function (item) {
        //$scope.AscTemplateScreenObj.IsShowAddUpdateScreen = true;
        item = $scope.AscTemplateScreenObj.TemplateList || '';
        $scope.AscTemplateScreenObj.SelectedTempItem = {};
        $scope.temp = {};
     
        let mInstanceAdd = $uibModal.open({
            "templateUrl": "templates/uibpopups/viewOrdersTemplatePopup.html",
            //"size": "lg",
            "backdrop": "static",
            "keyboard": false,
            //"scope": $scope,
            "windowClass": "modal__ninety--",
            "resolve": {
                "SelectedItem": function () { return item; },
            },
            "controller": function ($scope, $uibModal, $uibModalInstance, SelectedItem) {
                $scope.temp = $scope.temp || {};
                $scope.temp.IstemplateList = true;
                $scope.AscTemplateScreenObj = {
                    TemplateList: SelectedItem || [],

                }
                $scope.viewTemplate = function (item) {
                    $scope.temp = item || {};
                    $scope.temp.IstemplateList = false;
                    $scope.temp.Screen = 'Intraop';
                }

                $scope.temp.Screen = 'Intraop';
                $scope.AscChecklisttemplateSummuryViewObj = {
                    "Tab": 2,
                }
                $scope.ChecklisttemplateSummuryTab = function (Tab) {
                    $scope.AscChecklisttemplateSummuryViewObj.Tab = Tab || 1;

                    $scope.AscChecklisttemplateSummuryViewObj.IssShowAdd = false;
                    if ($scope.temp.Screen == 'Intraop' && $scope.AscChecklisttemplateSummuryViewObj.Tab != 2) {
                        $scope.AscChecklisttemplateSummuryViewObj.IssShowAdd = true;
                    }
                }
                $scope.OpenAsctemplateViasummury = function (item) {
                    $uibModalInstance.close(item);

                }
                $scope.uibclose = function () {
                    $uibModalInstance.dismiss("cancel");
                };
            }
        });
        mInstanceAdd.result.then(function (resp) {
            console.log(resp);
            resp = resp || '';
            if (resp != '') {
                $scope.changeASCTemplate(resp);

            }
        }, function (cancel) {
            console.log(cancel);
        });
    };

